window.MOSHI_N2_EXAMS = [{"id":"moshi_01","displayName":"Đề thi thử số 1 (Chuẩn Moshi to Taisaku)","subtitle":"47 câu • Full Mondai 1–8 (Từ vựng + Ngữ pháp)","badge":"Đề thi thử #1","questions":[{"mondai":1,"q":1,"prompt":"この地域では、古い建物を<u>保存</u>する取り組みが進められている。","options":["ほぞん","ほそん","ほうぞん","ほうそん"],"answer":1,"word_explain":"保存（ほぞん）: bảo tồn, lưu giữ. Lưu ý chữ 存 đọc có âm đục là ぞん và 保 không có trường âm.","translation_vi":"Ở khu vực này, các hoạt động bảo tồn những tòa nhà cổ đang được thúc đẩy."},{"mondai":1,"q":2,"prompt":"相手の立場を無視して、自分の意見ばかり<u>主張</u>するのはよくない。","options":["しゅちょ","しゅうちょ","しゅちょう","しゅうちょう"],"answer":3,"word_explain":"主張（しゅちょう）: chủ trương, khẳng định ý kiến. Chữ 主 đọc là しゅ (không trường âm), chữ 張 đọc là ちょう (có trường âm).","translation_vi":"Phớt lờ lập trường của đối phương mà chỉ khăng khăng chủ trương ý kiến của bản thân thì không tốt."},{"mondai":1,"q":3,"prompt":"台風の強風で、庭の大きな木が少し<u>傾いて</u>しまった。","options":["かたむいて","かたぶいて","ななむいて","ななぶいて"],"answer":1,"word_explain":"傾く（かたむく）: nghiêng đi, đổ nghiêng → chia thể て là 傾いて（かたむいて）.","translation_vi":"Do gió mạnh của cơn bão, cái cây lớn trong vườn đã bị nghiêng đi một chút."},{"mondai":1,"q":4,"prompt":"新しい企画について、部署内で活発な<u>議論</u>が行われた。","options":["ぎろ","ぎろん","きろ","きろん"],"answer":2,"word_explain":"議論（ぎろん）: thảo luận, tranh luận. Chữ 議 đọc là ぎ (âm đục), chữ 論 đọc là ろん.","translation_vi":"Một cuộc thảo luận sôi nổi về kế hoạch mới đã được tiến hành trong nội bộ phòng ban."},{"mondai":1,"q":5,"prompt":"この薬は食後に<u>服用</u>してくださいと薬剤師に言われた。","options":["ふよう","ふくゆう","ふっよう","ふくよう"],"answer":4,"word_explain":"服用（ふくよう）: uống thuốc, dùng thuốc (cách nói trang trọng/y tế). Chữ 服 đọc là ふく, chữ 用 đọc là よう.","translation_vi":"Tôi được dược sĩ dặn rằng hãy uống loại thuốc này sau bữa ăn."},{"mondai":2,"q":6,"prompt":"今年の夏は、例年に比べて降水量が<u>げんしょう</u>している。","options":["減小","減少","減省","減消"],"answer":2,"word_explain":"減少（げんしょう）: giảm sút, suy giảm (dùng chữ 少 trong 少ない - ít). Tránh nhầm với 小 (nhỏ), 省 (tỉnh lược) hay 消 (tiêu biến).","translation_vi":"Mùa hè năm nay, lượng mưa đang giảm sút so với mọi năm."},{"mondai":2,"q":7,"prompt":"取引先との会議の時間を<u>えんき</u>してもらえないだろうか。","options":["遠期","延記","延期","遠記"],"answer":3,"word_explain":"延期（えんき）: hoãn lại, dời kỳ hạn (延: kéo dài + 期: kỳ hạn). Tránh nhầm với 遠 (xa) hay 記 (ghi chép).","translation_vi":"Liệu có thể xin hoãn thời gian cuộc họp với đối tác được không nhỉ?"},{"mondai":2,"q":8,"prompt":"駅の近くは人通りが多くて、自転車では<u>つうこう</u>しにくい。","options":["通行","通交","通航","通向"],"answer":1,"word_explain":"通行（つうこう）: lưu thông, qua lại (người và xe cộ trên đường). Lưu ý 通航 là lưu thông đường thủy/hàng không.","translation_vi":"Gần nhà ga có nhiều người qua lại nên rất khó đi qua bằng xe đạp."},{"mondai":2,"q":9,"prompt":"会議の資料を全員に<u>くばって</u>ください。","options":["配って","渡って","与って","届って"],"answer":1,"word_explain":"配る（くばる）: phát, phân phát → chia thể て là 配って（くばって）. Các chữ 渡 (わたる), 与 (あたえる), 届 (とどく) không đọc là くばる.","translation_vi":"Hãy phát tài liệu cuộc họp cho tất cả mọi người."},{"mondai":2,"q":10,"prompt":"電気代が高くなったので、エアコンの使用を控えて<u>せつやく</u>を心がけている。","options":["節略","設約","節訳","節約"],"answer":4,"word_explain":"節約（せつやく）: tiết kiệm (節: tiết chế + 約: ước lược, giảm bớt). Tránh nhầm với 設 (thiết lập) hay 訳 (dịch).","translation_vi":"Vì tiền điện tăng cao nên tôi hạn chế dùng điều hòa và chú ý tiết kiệm."},{"mondai":3,"q":11,"prompt":"最近はキャッシュレス決済の普及により、現金を持ち歩かない人が増え、社会のデジタル(　　)が進んでいる。","options":["化","性","的","感"],"answer":1,"word_explain":"〜化（か）: hậu tố mang nghĩa \"- hóa\", biến đổi sang trạng thái đó. デジタル化 = sự số hóa.","translation_vi":"Gần đây, nhờ sự phổ cập của thanh toán không dùng tiền mặt, số người không mang tiền mặt tăng lên và quá trình số hóa xã hội đang tiến triển."},{"mondai":3,"q":12,"prompt":"パスワードを忘れてログインできなくなったので、システムに(　　)登録することにした。","options":["再","複","重","新"],"answer":1,"word_explain":"再〜（さい）: tiền tố mang nghĩa \"lại, lần nữa\". 再登録（さいとうろく）= đăng ký lại.","translation_vi":"Vì quên mật khẩu và không thể đăng nhập được nữa nên tôi quyết định đăng ký lại vào hệ thống."},{"mondai":3,"q":13,"prompt":"この洗剤は業務(　　)なので、一般のスーパーではあまり売られていない。","options":["用","向","専","製"],"answer":1,"word_explain":"〜用（よう）: hậu tố mang nghĩa \"dùng cho ~\". 業務用（ぎょうむよう）= dùng cho kinh doanh, chuyên dụng cho nhà hàng/công ty (trái với 家庭用).","translation_vi":"Loại chất tẩy rửa này là hàng dùng cho mục đích kinh doanh (công nghiệp) nên ít được bán ở các siêu thị thông thường."},{"mondai":4,"q":14,"prompt":"昨日の試合は緊張してしまい、練習してきた実力を十分に(　　)できなかった。","options":["発揮","発見","発行","発想"],"answer":1,"word_explain":"発揮（はっき）: phát huy (thường đi với 実力・能力・力). 発見: phát hiện; 発行: phát hành; 発想: ý tưởng, phát kiến.","translation_vi":"Trận đấu hôm qua tôi bị căng thẳng nên đã không thể phát huy đầy đủ thực lực mình đã luyện tập."},{"mondai":4,"q":15,"prompt":"引っ越しの荷造りが終わったと思ったら、まだ本棚の本が(　　)残っていた。","options":["ぎっしり","あっさり","うっかり","すっかり"],"answer":1,"word_explain":"ぎっしり: đầy ắp, chật ních không kẽ hở. あっさり: nhẹ nhàng, dễ dàng; うっかり: lơ đễnh, vô ý; すっかり: hoàn toàn.","translation_vi":"Cứ tưởng đã đóng gói đồ chuyển nhà xong xuôi rồi, thế mà sách trên giá vẫn còn đầy ắp chưa dọn."},{"mondai":4,"q":16,"prompt":"部長はいつも厳しいが、部下の相談には親身になって耳を(　　)くれる。","options":["寄せて","向けて","傾けて","あてて"],"answer":3,"word_explain":"耳を傾ける（みみをかたむける）: cụm cố định mang nghĩa \"lắng nghe một cách chăm chú, nghiêm túc\".","translation_vi":"Trưởng phòng lúc nào cũng nghiêm khắc, nhưng luôn tận tình lắng nghe khi cấp dưới tâm sự, hỏi ý kiến."},{"mondai":4,"q":17,"prompt":"長時間のパソコン作業で目が疲れたときは、遠くの景色を眺めて目を(　　)とよい。","options":["止める","休める","静める","冷める"],"answer":2,"word_explain":"目を休める（めをやすめる）: cho mắt nghỉ ngơi. 止める: dừng lại; 静める: làm dịu xuống; 冷める: nguội đi.","translation_vi":"Khi mắt bị mỏi do làm việc lâu với máy tính, ngắm nhìn phong cảnh ở xa để cho mắt nghỉ ngơi là rất tốt."},{"mondai":4,"q":18,"prompt":"このアプリの使い方はとても(　　)なので、初めての人でもすぐに操作できる。","options":["デリケート","ユニーク","シビア","シンプル"],"answer":4,"word_explain":"シンプル (simple): đơn giản, dễ hiểu. デリケート: tinh tế, nhạy cảm; ユニーク: độc đáo; シビア: nghiêm khắc, khắt khe.","translation_vi":"Cách sử dụng ứng dụng này rất đơn giản nên ngay cả người dùng lần đầu cũng có thể thao tác ngay được."},{"mondai":4,"q":19,"prompt":"彼女は周囲の反対を押し切って留学を決意したほど、(　　)の強い人だ。","options":["意識","意志","意欲","意見"],"answer":2,"word_explain":"意志（いし）: ý chí (cụm cố định: 意志が強い = ý chí mạnh mẽ). 意識: ý thức; 意欲: nhiệt huyết, ham muốn; 意見: ý kiến.","translation_vi":"Cô ấy là người có ý chí mạnh mẽ đến mức bất chấp sự phản đối của mọi người xung quanh để quyết tâm đi du học."},{"mondai":4,"q":20,"prompt":"台風の影響で野菜の収穫量が減り、スーパーでは価格が急激に(　　)している。","options":["成長","向上","上昇","発展"],"answer":3,"word_explain":"上昇（じょうしょう）: tăng lên (dùng cho giá cả, nhiệt độ, tỷ lệ). 成長: trưởng thành; 向上: nâng cao (trình độ, chất lượng); 発展: phát triển.","translation_vi":"Do ảnh hưởng của bão nên sản lượng thu hoạch rau giảm, và tại các siêu thị giá cả đang tăng vọt."},{"mondai":5,"q":21,"prompt":"会議の開始時刻が<u>迫っている</u>ので、急いで資料を準備しよう。","options":["早まっている","近づいている","決まっている","遅れている"],"answer":2,"word_explain":"迫る（せまる）≈ 近づく（ちかづく）: đến gần, sát nút (thời hạn, nguy cơ). 早まる: sớm hơn dự định; 決まる: được quyết định; 遅れる: bị trễ.","translation_vi":"Thời gian bắt đầu cuộc họp đang đến gần rồi, hãy khẩn trương chuẩn bị tài liệu thôi."},{"mondai":5,"q":22,"prompt":"彼の説明は<u>あいまいで</u>、結局何が言いたいのかよくわからなかった。","options":["細かくて","長すぎて","複雑で","はっきりしなくて"],"answer":4,"word_explain":"あいまい（曖昧）≈ はっきりしない: mơ hồ, không rõ ràng. 細かい: chi tiết; 長すぎる: quá dài; 複雑: phức tạp.","translation_vi":"Lời giải thích của anh ấy rất mơ hồ, rốt cuộc tôi chẳng hiểu anh ấy muốn nói gì."},{"mondai":5,"q":23,"prompt":"毎日少しずつでも練習を続ければ、<u>いずれ</u>上手に弾けるようになるよ。","options":["そのうち","たちまち","さっそく","あらかじめ"],"answer":1,"word_explain":"いずれ ≈ そのうち: rồi sớm muộn gì cũng, chẳng mấy chốc. たちまち: lập tức; さっそく: ngay lập tức; あらかじめ: từ trước.","translation_vi":"Nếu tiếp tục luyện tập mỗi ngày dù chỉ một chút thôi, rồi chẳng mấy chốc bạn sẽ chơi đàn giỏi thôi."},{"mondai":5,"q":24,"prompt":"新製品の売上が予想を大きく上回り、会社の業績が<u>回復した</u>。","options":["安定した","拡大した","立ち直った","変化した"],"answer":3,"word_explain":"回復する（かいふくする）≈ 立ち直る（たちなおる）: hồi phục, vực dậy trở lại trạng thái tốt. 安定: ổn định; 拡大: mở rộng; 変化: thay đổi.","translation_vi":"Doanh số sản phẩm mới vượt xa dự kiến nên thành tích kinh doanh của công ty đã phục hồi."},{"mondai":5,"q":25,"prompt":"いただいたご提案については、社内で十分に<u>検討します</u>。","options":["よく調べます","よく考えます","すぐ実行します","詳しく説明します"],"answer":2,"word_explain":"検討する（けんとうする）≈ よく考える: xem xét, cân nhắc kỹ lưỡng. よく調べる: điều tra kỹ; すぐ実行する: thực hiện ngay; 詳しく説明する: giải thích chi tiết.","translation_vi":"Về đề xuất mà quý vị đã gửi, chúng tôi sẽ xem xét kỹ lưỡng trong nội bộ công ty."},{"mondai":6,"q":26,"prompt":"そそっかしい","options":["弟は<u>そそっかしい</u>性格なので、よく傘や財布を電車に忘れてくる。","雨が降ってきたので、<u>そそっかしい</u>足取りで家へ帰った。","テストの時間が残り少なくなり、<u>そそっかしい</u>気持ちになった。","この料理は<u>そそっかしい</u>味付けなので、もう少し塩を足したほうがいい。"],"answer":1,"word_explain":"そそっかしい: hấp tấp, hậu đậu, cẩu thả (chỉ tính cách hoặc hành động của người). Câu 1 dùng đúng. Câu 2 sai (bước chân vội vã dùng 足早に), câu 3 sai (tâm trạng nóng ruột dùng 焦った), câu 4 sai (vị nhạt dùng 薄い).","translation_vi":"Em trai tôi có tính cách hấp tấp, cẩu thả nên rất hay để quên ô hoặc ví trên tàu điện."},{"mondai":6,"q":27,"prompt":"普及","options":["風邪が学校全体で<u>普及</u>して、学級閉鎖になった。","この10年でスマートフォンが急速に<u>普及</u>し、生活が大きく変わった。","駅前の再開発によって、新しい店がたくさん<u>普及</u>した。","彼女の優しい人柄は、クラスのみんなに<u>普及</u>している。"],"answer":2,"word_explain":"普及（ふきゅう）: phổ cập, lan rộng (dùng cho sản phẩm, công nghệ, kiến thức, thói quen trong xã hội). Câu 2 dùng đúng. Câu 1 phải dùng 流行 (lây lan dịch bệnh); câu 3 dùng 増えた; câu 4 dùng 知られている.","translation_vi":"Trong 10 năm qua, điện thoại thông minh đã phổ cập nhanh chóng và làm cuộc sống thay đổi rất nhiều."},{"mondai":6,"q":28,"prompt":"うっかり","options":["とても疲れていたので、ソファに座って<u>うっかり</u>休んだ。","遠くの山が霧の向こうに<u>うっかり</u>見えている。","大事な約束の日を<u>うっかり</u>忘れてしまい、友達に謝った。","部屋を掃除したら、気分まで<u>うっかり</u>した。"],"answer":3,"word_explain":"うっかり: lơ đễnh, vô ý, lỡ quên (đi với động từ chỉ sai sót như 忘れる・間違える). Câu 3 dùng đúng. Câu 1 nhầm với ゆっくり; câu 2 nhầm với うっすら/ぼんやり; câu 4 nhầm với すっきり.","translation_vi":"Tôi vô ý quên mất ngày hẹn quan trọng nên đã xin lỗi bạn mình."},{"mondai":6,"q":29,"prompt":"打ち合わせる","options":["知らない道だったので、通行人に場所を<u>打ち合わせた</u>。","二人の意見がなかなか<u>打ち合わせず</u>、会議は長引いた。","注文した商品と届いた商品の数を<u>打ち合わせた</u>。","イベントを成功させるために、当日の進行をスタッフ全員で<u>打ち合わせた</u>。"],"answer":4,"word_explain":"打ち合わせる（うちあわせる）: bàn bạc trước, trao đổi thống nhất kế hoạch/chi tiết trước khi tiến hành. Câu 4 dùng đúng. Câu 1 dùng 尋ねた; câu 2 dùng 一致せず/合わず; câu 3 dùng 照らし合わせた.","translation_vi":"Để sự kiện thành công, toàn bộ nhân viên đã bàn bạc thống nhất trước về trình tự tiến hành trong ngày hôm đó."},{"mondai":6,"q":30,"prompt":"絶妙","options":["山の頂上から見た夕日は、言葉にできないほど<u>絶妙</u>な高さだった。","あの選手は<u>絶妙</u>なタイミングでパスを出し、得点につなげた。","テストで満点を取って、先生から<u>絶妙</u>な評価をもらった。","彼は毎日欠かさず練習する、とても<u>絶妙</u>な努力家だ。"],"answer":2,"word_explain":"絶妙（ぜつみょう）: tuyệt diệu, hoàn hảo đến mức khó tả (thường dùng cho thời điểm タイミング, sự cân bằng バランス, hương vị 味付け). Câu 2 dùng đúng. Câu 1, 3, 4 đều dùng sai ngữ cảnh.","translation_vi":"Cầu thủ đó đã tung ra đường chuyền vào thời điểm tuyệt vời và dẫn đến bàn thắng."},{"mondai":7,"q":31,"prompt":"どんなに忙しくても、家族との食事の時間(　　)大切にしたいと思っている。","options":["だけは","にしては","にわたって","をめぐって"],"answer":1,"word_explain":"〜だけは: ít nhất là riêng ~, duy chỉ có ~ (nhấn mạnh mức tối thiểu muốn giữ gìn). にしては: so với ~ thì; にわたって: suốt khoảng; をめぐって: xoay quanh.","translation_vi":"Dù có bận rộn đến mấy, tôi vẫn muốn trân trọng ít nhất là riêng khoảng thời gian ăn cơm cùng gia đình."},{"mondai":7,"q":32,"prompt":"この町は夏は涼しくて過ごしやすい(　　)、冬は雪が多くて生活が大変だ。","options":["だけに","反面","あまり","ついでに"],"answer":2,"word_explain":"〜反面（はんめん）: mặt khác, trái lại (nêu hai mặt đối lập của cùng một sự vật). だけに: chính vì; あまり: quá mức đến nỗi; ついでに: nhân tiện.","translation_vi":"Thị trấn này mùa hè mát mẻ dễ chịu, nhưng mặt khác mùa đông lại nhiều tuyết nên cuộc sống rất vất vả."},{"mondai":7,"q":33,"prompt":"新しい図書館の建設(　　)、住民の間で賛成と反対の意見が対立している。","options":["にそって","にくらべて","をめぐって","をこめて"],"answer":3,"word_explain":"〜をめぐって: xoay quanh (thường đi với các từ tranh luận, đối lập, tranh giành như 対立する・議論する). にそって: dọc theo/tuân theo; にくらべて: so với; をこめて: dồn hết (tình cảm).","translation_vi":"Xoay quanh việc xây dựng thư viện mới, ý kiến tán thành và phản đối đang đối lập nhau giữa các cư dân."},{"mondai":7,"q":34,"prompt":"彼女は日本に来てまだ半年(　　)、敬語がとても上手だ。","options":["にとって","にかけては","に際して","にしては"],"answer":4,"word_explain":"〜にしては: so với tiêu chuẩn/tư cách/thời gian ~ thì (kết quả ngoài dự đoán). にとって: đối với; にかけては: về mặt ~ (thì giỏi nhất); に際して: nhân dịp.","translation_vi":"So với việc mới đến Nhật được nửa năm thì cô ấy dùng kính ngữ rất giỏi."},{"mondai":7,"q":35,"prompt":"インターネットは便利な道具だが、使い方(　　)、大きなトラブルにつながることもある。","options":["次第で","をもとに","に反して","のうえで"],"answer":1,"word_explain":"N＋次第で（しだいで）: tùy thuộc vào N. をもとに: dựa trên; に反して: trái với; のうえで: sau khi / về mặt.","translation_vi":"Internet là một công cụ tiện lợi, nhưng tùy thuộc vào cách sử dụng mà cũng có khi dẫn đến rắc rối lớn."},{"mondai":7,"q":36,"prompt":"うっかりアラームをかけ忘れた(　　)、大切な面接に遅刻してしまった。","options":["だけに","ばかりに","ものの","くせに"],"answer":2,"word_explain":"〜ばかりに: chỉ vì ~ mà (dẫn đến kết quả đáng tiếc, hối hận). だけに: chính vì (tương xứng); ものの: mặc dù; くせに: thế mà lại (chê trách).","translation_vi":"Chỉ vì lơ đễnh quên đặt báo thức mà tôi đã bị trễ buổi phỏng vấn quan trọng."},{"mondai":7,"q":37,"prompt":"雨が降り始めたので、急いで洗濯物を取り込もうとした(　　)、すでにかなり濡れていた。","options":["うちに","かわりに","ところ","まま"],"answer":3,"word_explain":"Vた＋ところ: khi làm thử/vừa làm ~ thì phát hiện ra kết quả bất ngờ ở vế sau. うちに: trong lúc; かわりに: thay vì; まま: giữ nguyên trạng thái.","translation_vi":"Thấy trời bắt đầu mưa nên tôi vội định rút đồ phơi vào, nhưng khi làm thế thì đồ đã ướt khá nhiều rồi."},{"mondai":7,"q":38,"prompt":"リーダーを引き受けた(　　)、最後まで責任を持ってやり遂げるつもりだ。","options":["ものの","あげく","わりに","からには"],"answer":4,"word_explain":"〜からには: một khi đã ~ thì (đi với vế sau thể hiện ý chí, quyết tâm, nghĩa vụ). ものの: mặc dù; あげく: kết cục sau thời gian dài; わりに: tuy ~ nhưng (so với).","translation_vi":"Một khi đã nhận lời làm trưởng nhóm thì tôi dự định sẽ có trách nhiệm hoàn thành đến cùng."},{"mondai":7,"q":39,"prompt":"どんなに優秀な人でも、一度も失敗を経験すること(　　)成功することは難しい。","options":["なしに","ばかりに","なりに","わりに"],"answer":1,"word_explain":"〜なしに / 〜ことなしに: mà không có ~, không làm ~. ばかりに: chỉ vì; なりに: theo cách riêng của; わりに: so với.","translation_vi":"Dù là người ưu tú đến đâu, thật khó để thành công mà không trải qua một lần thất bại nào."},{"mondai":7,"q":40,"prompt":"彼は料理が得意な(　　)、お菓子作りまでプロ並みにうまい。","options":["どころか","ばかりか","ものか","というか"],"answer":2,"word_explain":"〜ばかりか〜（まで・も）: không những ~ mà còn ~ (tăng tiến cùng chiều). どころか dùng cho tương phản ngược hẳn; ものか: làm gì có chuyện; というか: đúng hơn là.","translation_vi":"Anh ấy không chỉ giỏi nấu ăn mà ngay cả việc làm bánh cũng khéo ngang tầm chuyên nghiệp."},{"mondai":7,"q":41,"prompt":"子どもが夜遅くまで帰ってこないので、母親は心配で(　　)。","options":["しかたがある","いられない","たまらない","かまわない"],"answer":3,"word_explain":"〜て/で＋たまらない: vô cùng, không chịu nổi (diễn tả cảm xúc, cảm giác ở mức độ cực điểm). Lưu ý しかたがない mới đúng (không phải しかたがある); いられない không đi sau 心配で.","translation_vi":"Vì con đến tối muộn vẫn chưa về nên người mẹ lo lắng vô cùng."},{"mondai":7,"q":42,"prompt":"部長：「来週の出張のホテル、もう予約してくれた？」\\n部下：「すみません、今すぐ(　　)。」","options":["予約なさいます","予約されます","予約くださいます","予約いたします"],"answer":4,"word_explain":"いたす là khiêm nhường ngữ của する, dùng khi người nói (cấp dưới) nói về hành động của bản thân với cấp trên. Các đáp án 1, 2, 3 đều là tôn kính ngữ (dùng cho hành động của đối phương).","translation_vi":"Trưởng phòng: \"Cậu đã đặt khách sạn cho chuyến công tác tuần tới chưa?\"\\nCấp dưới: \"Xin lỗi anh, tôi sẽ đặt ngay bây giờ ạ.\""},{"mondai":8,"q":43,"prompt":"今年の夏は、　＿＿＿　＿＿＿　★　＿＿＿　が多い。","options":["体調を崩す","のせいで","あまりの暑さ","人"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 2 → 1(★) → 4 (あまりの暑さ のせいで 体調を崩す 人). Cấu trúc 「あまりのN＋のせいで」 (do quá N) bổ nghĩa cho cụm 「体調を崩す人」 (người bị ốm/suy nhược). Vị trí ★ là đáp án 1.","translation_vi":"Mùa hè năm nay, có rất nhiều người bị suy nhược sức khỏe do trời quá nóng."},{"mondai":8,"q":44,"prompt":"昨日の会議では、　＿＿＿　＿＿＿　★　＿＿＿　決まった。","options":["ことに","延期する","新製品の発売","を来月に"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → 2(★) → 1 (新製品の発売 を来月に 延期する ことに). Cụm 「〜を来月に延期する」 (hoãn ~ sang tháng sau) kết hợp với mẫu ngữ pháp 「Vる＋ことに決まった」 (đã được quyết định là ~). Vị trí ★ là đáp án 2.","translation_vi":"Trong cuộc họp hôm qua, đã quyết định sẽ hoãn việc ra mắt sản phẩm mới sang tháng sau."},{"mondai":8,"q":45,"prompt":"彼女は英語が　＿＿＿　＿＿＿　★　＿＿＿　話せるそうだ。","options":["だけでなく","まで","フランス語や中国語","話せる"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 1 → 3(★) → 2 (話せる だけでなく フランス語や中国語 まで). Cấu trúc 「〜だけでなく〜まで」 (không chỉ ~ mà còn cả ~). Vị trí ★ là đáp án 3.","translation_vi":"Nghe nói cô ấy không chỉ nói được tiếng Anh mà còn nói được cả tiếng Pháp và tiếng Trung nữa."},{"mondai":8,"q":46,"prompt":"高い値段が　＿＿＿　＿＿＿　★　＿＿＿　わけではない。","options":["からといって","いい","ついている","必ずしも品質が"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → 4(★) → 2 (ついている からといって 必ずしも品質が いい). Mẫu câu N2 kinh điển 「〜からといって、必ずしも〜わけではない」 (không phải cứ ~ thì nhất định sẽ ~). Vị trí ★ là đáp án 4.","translation_vi":"Không hẳn là cứ có giá đắt thì chất lượng sẽ tốt."},{"mondai":8,"q":47,"prompt":"いくら疲れていても、　＿＿＿　＿＿＿　★　＿＿＿　いけない。","options":["明日のテストの","せずに","寝てしまっては","勉強を"],"answer":2,"word_explain":"Thứ tự đúng: 1 → 4 → 2(★) → 3 (明日のテストの 勉強を せずに 寝てしまっては). Cụm 「明日のテストの勉強をせずに」 (không học bài cho bài kiểm tra ngày mai) đi với 「寝てしまってはいけない」 (không được ngủ mất). Vị trí ★ là đáp án 2.","translation_vi":"Dù có mệt đến mấy thì cũng không được ngủ quên mà không học bài cho kỳ thi ngày mai."}]},{"id":"moshi_02","displayName":"Đề thi thử số 2 (Chuẩn Moshi to Taisaku)","subtitle":"47 câu • Full Mondai 1–8 (Từ vựng + Ngữ pháp)","badge":"Đề thi thử #2","questions":[{"mondai":1,"q":1,"prompt":"新しいシステムの導入により、業務の<u>効率</u>が大幅に改善された。","options":["こうりつ","こうりゅう","こおりつ","かくりつ"],"answer":1,"word_explain":"効率（こうりつ - HIỆU SUẤT）: hiệu suất, hiệu quả công việc. Chú ý trường âm 「こう」 và tránh nhầm với 確立（かくりつ - xác lập）hay 交流（こうりゅう - giao lưu）.","translation_vi":"Nhờ việc đưa hệ thống mới vào sử dụng, hiệu suất công việc đã được cải thiện đáng kể."},{"mondai":1,"q":2,"prompt":"今回の調査結果については、専門家の間でも意見が<u>対立</u>している。","options":["たいりゅう","たいりつ","ついりつ","たいだつ"],"answer":2,"word_explain":"対立（たいりつ - ĐỐI LẬP）: sự đối lập, mâu thuẫn. Âm đọc của 対 trong từ ghép này là 「たい」, 立 là 「りつ」.","translation_vi":"Về kết quả khảo sát lần này, ngay cả trong giới chuyên gia cũng có sự đối lập về ý kiến."},{"mondai":1,"q":3,"prompt":"大学側は、来年度から新しい奨学金制度を<u>設ける</u>と発表した。","options":["さだめる","とどける","もうける","まうける"],"answer":3,"word_explain":"設ける（もうける - THIẾT）: thiết lập, lập ra (chế độ, quy định, cơ hội). Tránh nhầm với 定める（さだめる）hay 届ける（とどける）.","translation_vi":"Phía trường đại học thông báo sẽ thiết lập chế độ học bổng mới từ năm học tới."},{"mondai":1,"q":4,"prompt":"このアプリは操作が簡単なので、機械が苦手な人にも<u>普及</u>している。","options":["ふぎゅう","ふきょう","ふきゅ","ふきゅう"],"answer":4,"word_explain":"普及（ふきゅう - PHỔ CẬP）: sự phổ biến, lan rộng. Chú ý 級/及 đọc là 「きゅう」 có trường âm và không có âm đục.","translation_vi":"Ứng dụng này thao tác đơn giản nên đang phổ biến cả với những người không rành về máy móc."},{"mondai":1,"q":5,"prompt":"重要なデータを外部に<u>漏らす</u>ことのないよう、管理を徹底してください。","options":["ちらす","もらす","さらす","へらす"],"answer":2,"word_explain":"漏らす（もらす - LẬU）: làm rò rỉ, để lộ (thông tin, dữ liệu). Tránh nhầm với 散らす（ちらす - làm vương vãi）hay 減らす（へらす - làm giảm）.","translation_vi":"Hãy quản lý chặt chẽ để không làm rò rỉ dữ liệu quan trọng ra bên ngoài."},{"mondai":2,"q":6,"prompt":"会議の資料は、事前に参加者に<u>はいふ</u>しておく予定です。","options":["配布","配市","配希","記布"],"answer":1,"word_explain":"配布（はいふ - PHỐI BỐ）: sự phân phát (tài liệu, tờ rơi). Gồm chữ 配 (phân phối) và chữ 布 (bố trí, phân phát).","translation_vi":"Tài liệu cuộc họp dự kiến sẽ được phát trước cho những người tham gia."},{"mondai":2,"q":7,"prompt":"海外の取引先と<u>けいやく</u>を結ぶ前に、条件を細かく確認した。","options":["軽約","経約","契約","計約"],"answer":3,"word_explain":"契約（けいやく - KHẾ ƯỚC）: hợp đồng. Cụm từ cố định: 契約を結ぶ (ký kết hợp đồng).","translation_vi":"Trước khi ký kết hợp đồng với đối tác nước ngoài, tôi đã kiểm tra kỹ các điều kiện."},{"mondai":2,"q":8,"prompt":"生徒たちの学習意欲を高めるため、授業の進め方を<u>くふう</u>している。","options":["公夫","工夫","工風","功風"],"answer":2,"word_explain":"工夫（くふう - CÔNG PHU）: sự tìm tòi, cải tiến, sáng tạo cách làm. Chú ý chữ 夫 chứ không phải chữ 風.","translation_vi":"Để nâng cao động lực học tập của học sinh, tôi đang tìm tòi sáng tạo cách tiến hành bài giảng."},{"mondai":2,"q":9,"prompt":"省エネ技術の開発により、電力の消費量を大きく<u>さくげん</u>できた。","options":["削滅","作減","策減","削減"],"answer":4,"word_explain":"削減（さくげん - TƯỚC GIẢM）: sự cắt giảm (chi phí, điện năng, nhân sự). Gồm chữ 削 (gọt, cắt bỏ) và chữ 減 (giảm).","translation_vi":"Nhờ phát triển công nghệ tiết kiệm năng lượng, chúng tôi đã có thể cắt giảm đáng kể lượng điện tiêu thụ."},{"mondai":2,"q":10,"prompt":"新聞の記事を読んで、環境問題に対する関心が<u>ふかまった</u>。","options":["深まった","探まった","濃まった","厚まった"],"answer":1,"word_explain":"深まる（ふかまる - THÂM）: trở nên sâu sắc hơn (関心が深まる: sự quan tâm sâu sắc hơn). Tránh nhầm mặt chữ với 探 (tìm kiếm).","translation_vi":"Sau khi đọc bài báo, sự quan tâm của tôi đối với vấn đề môi trường đã trở nên sâu sắc hơn."},{"mondai":3,"q":11,"prompt":"レポートに不備が見つかったため、来週までに(　　)提出することになった。","options":["再","復","重","副"],"answer":1,"word_explain":"Tiền tố 再〜（さい〜）mang nghĩa \"lại, lần nữa\": 再提出（さいていしゅつ - nộp lại）, 再放送 (phát sóng lại), 再開発 (tái phát triển).","translation_vi":"Vì phát hiện thiếu sót trong báo cáo nên đã quyết định phải nộp lại trước tuần sau."},{"mondai":3,"q":12,"prompt":"オンライン授業に切り替えてから、学生の出席(　　)が以前より高くなった。","options":["度","率","量","力"],"answer":2,"word_explain":"Hậu tố 〜率（〜りつ）biểu thị tỷ lệ phần trăm: 出席率（しゅっせきりつ - tỷ lệ tham dự/chuyên cần）, 合格率 (tỷ lệ đỗ).","translation_vi":"Kể từ khi chuyển sang học trực tuyến, tỷ lệ chuyên cần của sinh viên đã cao hơn trước."},{"mondai":3,"q":13,"prompt":"このソフトウェアは、中小企業(　　)に開発された会計管理システムです。","options":["宛て","寄り","向け","行き"],"answer":3,"word_explain":"Hậu tố 〜向け（〜むけ）mang nghĩa \"dành cho đối tượng nào đó\": 中小企業向け (dành cho doanh nghiệp vừa và nhỏ). 宛て dùng cho người nhận thư, 寄り là thiên về, 行き là đi tới.","translation_vi":"Phần mềm này là hệ thống quản lý kế toán được phát triển dành cho các doanh nghiệp vừa và nhỏ."},{"mondai":4,"q":14,"prompt":"新製品の発売に向けて、社内で宣伝方法の(　　)を重ねている。","options":["検索","検診","検討","検査"],"answer":3,"word_explain":"検討（けんとう - KIỂM THẢO）: xem xét, thảo luận kỹ lưỡng. Cụm hay gặp: 検討を重ねる. 検索 (tìm kiếm dữ liệu), 検診 (khám sức khỏe), 検査 (kiểm tra, xét nghiệm).","translation_vi":"Hướng tới việc ra mắt sản phẩm mới, trong nội bộ công ty đang liên tục xem xét các phương pháp quảng bá."},{"mondai":4,"q":15,"prompt":"最新のAI技術を活用すれば、大量のデータを短時間で(　　)することができる。","options":["処置","修理","手入れ","処理"],"answer":4,"word_explain":"処理（しょり - XỬ LÝ）: xử lý (dữ liệu, công việc, hồ sơ). 処置 (xử trí y tế/khẩn cấp), 修理 (sửa chữa), 手入れ (bảo dưỡng, chăm sóc).","translation_vi":"Nếu tận dụng công nghệ AI mới nhất, có thể xử lý một lượng lớn dữ liệu trong thời gian ngắn."},{"mondai":4,"q":16,"prompt":"少子化の影響で、この地域の小学校の児童数は(　　)減少している。","options":["いっそ","しだいに","かりに","わざわざ"],"answer":2,"word_explain":"しだいに（次第に）: dần dần, từng chút một (thường đi với động từ chỉ sự biến đổi như 減少する, 増える). いっそ (thà rằng), かりに (giả sử), わざわざ (cất công).","translation_vi":"Do ảnh hưởng của tình trạng giảm tỷ lệ sinh, số lượng học sinh tiểu học ở khu vực này đang giảm dần."},{"mondai":4,"q":17,"prompt":"長年培ってきた製造の(　　)を、若手社員にしっかりと引き継いでいきたい。","options":["ノウハウ","アピール","イメージ","アプローチ"],"answer":1,"word_explain":"ノウハウ（know-how）: bí quyết, kiến thức kỹ thuật thực tiễn tích lũy qua kinh nghiệm. アピール (thể hiện, quảng bá), イメージ (hình ảnh), アプローチ (cách tiếp cận).","translation_vi":"Tôi muốn truyền lại một cách vững chắc những bí quyết sản xuất đã tích lũy nhiều năm cho các nhân viên trẻ."},{"mondai":4,"q":18,"prompt":"最近の物価上昇を受け、我が社でも経費の使い方を(　　)必要がある。","options":["見送る","見落とす","見直す","見慣れる"],"answer":3,"word_explain":"見直す（みなおす）: xem xét lại, đánh giá lại (kế hoạch, chi tiêu, chế độ). 見送る (tiễn/tạm hoãn), 見落とす (bỏ sót), 見慣れる (nhìn quen mắt).","translation_vi":"Trước tình hình giá cả leo thang gần đây, công ty chúng tôi cũng cần xem xét lại cách sử dụng chi phí."},{"mondai":4,"q":19,"prompt":"教授の説明は要点が(　　)にまとめられており、学生たちにも非常に好評だった。","options":["厳重","真剣","慎重","簡潔"],"answer":4,"word_explain":"簡潔（かんけつ - GIẢN KHIẾT）: ngắn gọn, súc tích, rõ ý. 厳重 (nghiêm ngặt), 真剣 (nghiêm túc), 慎重 (thận trọng).","translation_vi":"Lời giải thích của giáo sư tóm lược các ý chính một cách súc tích nên được các sinh viên đánh giá rất cao."},{"mondai":4,"q":20,"prompt":"来年の新キャンパス開校に向けて、建設工事が(　　)進んでいる。","options":["続々と","着々と","黙々と","堂々と"],"answer":2,"word_explain":"着々と（ちゃくちゃくと）: tiến triển đều đặn, chắc chắn theo đúng kế hoạch. 続々と (nối tiếp nhau), 黙々と (lặng lẽ làm), 堂々と (đường hoàng).","translation_vi":"Hướng tới việc khai trương cơ sở mới vào năm sau, công trình xây dựng đang tiến triển đều đặn."},{"mondai":5,"q":21,"prompt":"このプロジェクトを成功させるには、各部署の協力が<u>不可欠</u>だ。","options":["なくてはならない","あまり必要ない","すぐにはできない","とても珍しい"],"answer":1,"word_explain":"不可欠（ふかけつ - BẤT KHẢ KHUYẾT）= なくてはならない: không thể thiếu, thiết yếu.","translation_vi":"Để dự án này thành công, sự hợp tác của các phòng ban là không thể thiếu."},{"mondai":5,"q":22,"prompt":"新製品の売り上げは、発売当初の予想を<u>上回った</u>。","options":["より低くなった","より多くなった","とほぼ同じだった","と大きく違った"],"answer":2,"word_explain":"上回る（うわまわる）= より多くなる／高くなる: vượt qua, cao hơn mức nào đó (trái nghĩa với 下回る).","translation_vi":"Doanh số của sản phẩm mới đã vượt qua dự đoán ban đầu khi ra mắt."},{"mondai":5,"q":23,"prompt":"海外留学の経験は、その後のキャリア形成において大きな<u>メリット</u>になった。","options":["負担","課題","利点","条件"],"answer":3,"word_explain":"メリット（merit）= 利点（りてん）: ưu điểm, lợi thế, điểm có lợi. 負担 (gánh nặng), 課題 (vấn đề cần giải quyết), 条件 (điều kiện).","translation_vi":"Kinh nghiệm du học nước ngoài đã trở thành một lợi thế lớn trong việc xây dựng sự nghiệp sau đó."},{"mondai":5,"q":24,"prompt":"会議の開始時刻を、急な都合により30分<u>繰り下げる</u>ことになった。","options":["早くする","短くする","中止する","遅らせる"],"answer":4,"word_explain":"繰り下げる（くりさげる）= 遅らせる: dời lại, lùi lịch trình muộn hơn (trái nghĩa với 繰り上げる = đẩy sớm lên).","translation_vi":"Do có việc đột xuất nên thời gian bắt đầu cuộc họp đã được lùi lại 30 phút."},{"mondai":5,"q":25,"prompt":"この研究をまとめるために、<u>膨大な</u>資料を調査した。","options":["非常に古い","非常に多い","非常に難しい","非常に詳しい"],"answer":2,"word_explain":"膨大な（ぼうだいな - BÀNH ĐẠI）= 非常に多い／極めて大きい: khổng lồ, cực kỳ nhiều (thường dùng cho 資料, データ, 費用).","translation_vi":"Để tổng hợp nghiên cứu này, tôi đã khảo sát một lượng tài liệu khổng lồ."},{"mondai":6,"q":26,"prompt":"把握","options":["転ばないように、手すりをしっかりと<u>把握</u>しながら階段を下りた。","チームリーダーは、メンバー全員の進捗状況を常に<u>把握</u>しておく必要がある。","この新しい機械は操作が複雑で、なかなかうまく<u>把握</u>できない。","昨日のニュースで見た俳優の名前が思い出せず、頭の中で<u>把握</u>しようとした。"],"answer":2,"word_explain":"把握（はあく - BẢ ÁC）: nắm bắt, hiểu rõ (tình hình, nội dung, vấn đề). Câu 2 dùng đúng cụm 「状況を把握する」. Câu 1 phải dùng 握る (nắm tay vịn), câu 3 dùng 使いこなす (sử dụng thành thạo), câu 4 dùng 思い出す (nhớ lại).","translation_vi":"Trưởng nhóm cần phải luôn nắm bắt tình hình tiến độ của tất cả các thành viên."},{"mondai":6,"q":27,"prompt":"せっかく","options":["<u>せっかく</u>雨が降ってきたので、傘を持って出かけよう。","このパソコンは<u>せっかく</u>壊れてしまったので、買い替えるしかない。","<u>せっかく</u>の週末なのに、急な仕事が入って休めなくなってしまった。","彼は毎日<u>せっかく</u>同じ時間に起きて、ジョギングを続けている。"],"answer":3,"word_explain":"せっかく: mất công, hiếm lắm mới có (dịp tốt/công sức), thường kèm sắc thái tiếc nuối khi đi với のに. Câu 3 「せっかくの週末なのに」 đúng tự nhiên. Các câu 1, 2, 4 không mang ý nghĩa dịp quý giá hay công sức đáng trân trọng.","translation_vi":"Hiếm lắm mới đến cuối tuần mà lại có việc đột xuất nên chẳng được nghỉ."},{"mondai":6,"q":28,"prompt":"解消","options":["長年の人手不足を<u>解消</u>するため、新しい採用計画を立ち上げた。","不要になった古いパソコンのデータは、完全に<u>解消</u>してから処分した。","会議の予定が変更になったため、元のスケジュールを<u>解消</u>した。","ホワイトボードに書いた文字を、授業が終わってからきれいに<u>解消</u>した。"],"answer":1,"word_explain":"解消（かいしょう - GIẢI TIÊU）: giải quyết, xóa bỏ (tình trạng thiếu hụt, căng thẳng, hiểu lầm, bất mãn). Câu 1 「人手不足を解消する」 hoàn toàn chính xác. Câu 2 phải dùng 消去/削除, câu 3 dùng 取り消す, câu 4 dùng 消す.","translation_vi":"Để giải quyết tình trạng thiếu nhân lực kéo dài nhiều năm, công ty đã khởi động kế hoạch tuyển dụng mới."},{"mondai":6,"q":29,"prompt":"著しい","options":["このレストランの料理は、とても<u>著しい</u>味がして人気がある。","彼女はいつも<u>著しい</u>笑顔で、お客さんを迎えている。","今日は風が強くて、外はとても<u>著しい</u>天気だ。","近年、生成AIの分野における技術の進歩には<u>著しい</u>ものがある。"],"answer":4,"word_explain":"著しい（いちじるしい - TRỨ）: rõ rệt, vượt bậc, đáng kể (dùng cho sự tiến bộ, tăng trưởng, thay đổi). Câu 4 「進歩には著しいものがある」 rất chuẩn văn phong báo chí/học thuật. Không dùng cho mùi vị, nụ cười hay thời tiết.","translation_vi":"Những năm gần đây, sự tiến bộ của công nghệ trong lĩnh vực AI tạo sinh có những bước phát triển vượt bậc."},{"mondai":6,"q":30,"prompt":"差し支える","options":["明日の会議は重要な内容なので、ぜひ<u>差し支えて</u>参加してください。","風邪をひいたが、軽い症状なので日常の業務には<u>差し支えない</u>。","新しいアプリの使い方がわからず、友人に<u>差し支えて</u>教えてもらった。","電車が遅延したため、予定より早く駅に<u>差し支えて</u>しまった。"],"answer":2,"word_explain":"差し支える（さしつかえる）: gây trở ngại, ảnh hưởng đến (công việc, sinh hoạt), rất hay dùng ở dạng phủ định 「〜に差し支えない」 (không gây trở ngại). Câu 2 dùng đúng cấu trúc và ngữ nghĩa.","translation_vi":"Tôi bị cảm, nhưng triệu chứng nhẹ nên không ảnh hưởng đến công việc hàng ngày."},{"mondai":7,"q":31,"prompt":"AI技術の急速な発展(　　)、従来の働き方や教育のあり方も大きく変化している。","options":["に伴って","に限って","に反して","に代わって"],"answer":1,"word_explain":"〜に伴って（にともなって）: đi đôi với, cùng với sự biến đổi A thì B cũng thay đổi theo. に限って (riêng lúc/chỉ có), に反して (trái với), に代わって (thay cho).","translation_vi":"Cùng với sự phát triển nhanh chóng của công nghệ AI, cách thức làm việc và hình thức giáo dục truyền thống cũng đang thay đổi lớn."},{"mondai":7,"q":32,"prompt":"新しい再開発計画の是非(　　)、地域住民と市役所の議論が続いている。","options":["を通じて","をめぐって","をもとに","に沿って"],"answer":2,"word_explain":"〜をめぐって: xoay quanh (một vấn đề gây tranh cãi, thảo luận hoặc đối lập ý kiến). Thường đi với 議論, 対立, 争い. を通じて (thông qua), をもとに (dựa trên), に沿って (dọc theo/tuân theo).","translation_vi":"Cuộc tranh luận giữa cư dân địa phương và chính quyền thành phố về tính đúng đắn của kế hoạch tái phát triển mới vẫn đang tiếp diễn."},{"mondai":7,"q":33,"prompt":"新システムへの移行(　　)、すべての社員を対象に操作説明会を実施いたします。","options":["に対して","に比べて","に際して","にとって"],"answer":3,"word_explain":"〜に際して（にさいして）: nhân dịp, khi tiến hành một sự kiện/hành động quan trọng (cách nói trang trọng). に対して (đối với), に比べて (so với), にとって (đối với lập trường của).","translation_vi":"Nhân dịp chuyển đổi sang hệ thống mới, chúng tôi sẽ tổ chức buổi hướng dẫn thao tác cho toàn thể nhân viên."},{"mondai":7,"q":34,"prompt":"最新の機能がたくさん付いている製品が、必ずしも使いやすい(　　)。","options":["にすぎない","にほかならない","に違いない","とは限らない"],"answer":4,"word_explain":"必ずしも〜とは限らない: không hẳn lúc nào cũng... (phủ định một phần). にすぎない (chỉ là), にほかならない (chính là), に違いない (chắc chắn là).","translation_vi":"Sản phẩm có nhiều tính năng mới nhất không hẳn lúc nào cũng dễ sử dụng."},{"mondai":7,"q":35,"prompt":"このオンライン講座は、語学力を伸ばせる(　　)、海外のビジネス文化も学べる点が魅力だ。","options":["ばかりでなく","だけでなくては","どころか","ものの"],"answer":1,"word_explain":"〜ばかりでなく〜も: không chỉ... mà còn... (tương đương だけでなく). どころか (huống chi là/trái lại), ものの (mặc dù).","translation_vi":"Khóa học trực tuyến này có điểm hấp dẫn là không chỉ giúp nâng cao năng lực ngoại ngữ mà còn có thể học được văn hóa kinh doanh nước ngoài."},{"mondai":7,"q":36,"prompt":"リモートワークの定着により、地方へ移住して働く若者が増え(　　)。","options":["きっている","つつある","かねない","きれない"],"answer":2,"word_explain":"V-ます + つつある: đang dần..., đang trong quá trình biến đổi (dùng trong văn viết, báo chí). きっている (hoàn toàn), かねない (có nguy cơ), きれない (không thể làm hết).","translation_vi":"Nhờ việc làm từ xa trở nên phổ biến ổn định, số lượng người trẻ chuyển về địa phương sinh sống và làm việc đang dần tăng lên."},{"mondai":7,"q":37,"prompt":"悪天候(　　)、本日の企業説明会には予想を上回る学生が参加した。","options":["のおかげで","のせいで","にもかかわらず","にしたがって"],"answer":3,"word_explain":"〜にもかかわらず: mặc dù, bất chấp (kết quả trái ngược với dự đoán từ vế trước). のおかげで (nhờ có), のせいで (tại vì), にしたがって (cùng với/theo).","translation_vi":"Mặc dù thời tiết xấu, số lượng sinh viên tham gia buổi giới thiệu doanh nghiệp hôm nay vẫn vượt quá dự đoán."},{"mondai":7,"q":38,"prompt":"面接の結果につきましては、決まり(　　)メールにてご連絡いたします。","options":["ながら","うちに","とおり","次第"],"answer":4,"word_explain":"V-ます + 次第（しだい）: ngay sau khi... thì sẽ làm hành động tiếp theo (cách nói trang trọng trong công việc). 決まり次第 (ngay khi có quyết định).","translation_vi":"Về kết quả phỏng vấn, ngay khi có quyết định chúng tôi sẽ liên hệ qua email."},{"mondai":7,"q":39,"prompt":"原材料費の高騰が続いており、来月から商品の価格を値上げ(　　)状況だ。","options":["せざるを得ない","しっこない","するどころではない","しないはずがない"],"answer":1,"word_explain":"〜ざるを得ない: buộc phải, không còn cách nào khác ngoài việc phải làm (lưu ý động từ する chia thành せざるを得ない). しっこない (chắc chắn không làm), するどころではない (chẳng thể làm được vì bận/khó khăn).","translation_vi":"Chi phí nguyên vật liệu tiếp tục tăng cao nên đang ở trong tình thế buộc phải tăng giá sản phẩm từ tháng sau."},{"mondai":7,"q":40,"prompt":"締め切りが明日に迫っていて、今は昼休みを取る(　　)。","options":["わけがない","どころではない","にすぎない","ほかない"],"answer":2,"word_explain":"〜どころではない: không phải lúc để..., chẳng còn tâm trí/thời gian đâu mà làm việc đó. わけがない (không thể nào), にすぎない (chỉ là), ほかない (chỉ còn cách).","translation_vi":"Hạn chót đã cận kề ngày mai rồi, bây giờ chẳng còn thời gian đâu mà nghỉ trưa nữa."},{"mondai":7,"q":41,"prompt":"パスワードを簡単なものにしておくと、不正アクセスを許し(　　)ので注意が必要だ。","options":["がたい","きれない","かねない","つつある"],"answer":3,"word_explain":"V-ます + かねない: có nguy cơ xảy ra một kết quả xấu/không mong muốn. がたい (khó mà), きれない (không thể làm hết), つつある (đang dần).","translation_vi":"Nếu để mật khẩu quá đơn giản thì có nguy cơ bị truy cập trái phép, nên cần phải chú ý."},{"mondai":7,"q":42,"prompt":"契約書の内容を十分に確認した(　　)、署名をお願いします。","options":["うちに","ところに","わりに","うえで"],"answer":4,"word_explain":"V-た + うえで: sau khi làm xong hành động A rồi mới tiến hành hành động B. うちに (trong khi), ところに (đúng lúc), わりに (tuy... nhưng/so với).","translation_vi":"Sau khi xác nhận kỹ nội dung hợp đồng, vui lòng ký tên."},{"mondai":8,"q":43,"prompt":"この報告書は、＿＿＿　＿＿＿　★　＿＿＿　と評価されている。","options":["非常に","説得力がある","データに基づいている","だけに"],"answer":1,"word_explain":"Thứ tự đúng: 3 (データに基づいている) → 4 (だけに) → 1 (非常に) → 2 (説得力がある). Ngữ pháp 「〜だけに」 (chính vì... nên càng...). Vị trí ★ là đáp án 1.","translation_vi":"Bản báo cáo này được đánh giá là chính vì dựa trên dữ liệu nên có sức thuyết phục rất lớn."},{"mondai":8,"q":44,"prompt":"海外での勤務においては、＿＿＿　＿＿＿　★　＿＿＿　求められる。","options":["理解する力が","語学力","異文化を","もさることながら"],"answer":3,"word_explain":"Thứ tự đúng: 2 (語学力) → 4 (もさることながら) → 3 (異文化を) → 1 (理解する力が). Ngữ pháp 「Aもさることながら、B」 (A đương nhiên là thế, nhưng B cũng...). Vị trí ★ là đáp án 3.","translation_vi":"Khi làm việc ở nước ngoài, năng lực ngoại ngữ đương nhiên là cần thiết, nhưng hơn thế nữa, khả năng thấu hiểu các nền văn hóa khác cũng được đòi hỏi."},{"mondai":8,"q":45,"prompt":"今回の停電　＿＿＿　＿＿＿　★　＿＿＿　ことになった。","options":["見直す","防災体制を","をきっかけに","社内の"],"answer":2,"word_explain":"Thứ tự đúng: 3 (をきっかけに) → 4 (社内の) → 2 (防災体制を) → 1 (見直す). Ngữ pháp 「〜をきっかけに」 (lấy việc gì làm cơ hội/bước ngoặt). Vị trí ★ là đáp án 2.","translation_vi":"Lấy sự cố mất điện lần này làm cơ hội, công ty đã quyết định xem xét lại hệ thống phòng chống thiên tai trong nội bộ."},{"mondai":8,"q":46,"prompt":"お客様との約束である　＿＿＿　＿＿＿　★　＿＿＿　いかない。","options":["わけには","途中で","以上","投げ出す"],"answer":4,"word_explain":"Thứ tự đúng: 3 (以上) → 2 (途中で) → 4 (投げ出す) → 1 (わけには). Ngữ pháp 「〜以上」 (một khi đã...) kết hợp 「〜わけにはいかない」 (không thể làm...). Vị trí ★ là đáp án 4.","translation_vi":"Một khi đã là lời hứa với khách hàng thì không thể bỏ dở giữa chừng được."},{"mondai":8,"q":47,"prompt":"多くの利用者からの　＿＿＿　＿＿＿　★　＿＿＿　ことになった。","options":["追加する","新しい機能を","要望","にこたえて"],"answer":2,"word_explain":"Thứ tự đúng: 3 (要望) → 4 (にこたえて) → 2 (新しい機能を) → 1 (追加する). Ngữ pháp 「〜にこたえて」 (đáp lại yêu cầu, kỳ vọng). Vị trí ★ là đáp án 2.","translation_vi":"Đáp lại yêu cầu từ nhiều người dùng, chúng tôi đã quyết định bổ sung tính năng mới."}]},{"id":"moshi_03","displayName":"Đề thi thử số 3 (Chuẩn Goukaku Dekiru)","subtitle":"47 câu • Full Mondai 1–8 (Từ vựng + Ngữ pháp)","badge":"Đề thi thử #3","questions":[{"mondai":1,"q":1,"prompt":"工場からの排水による川の<u>汚染</u>が深刻な問題になっている。","options":["おせん","おぜん","うせん","うぜん"],"answer":1,"word_explain":"汚染（おせん）: ô nhiễm (Ô NHIỄM). Chú ý âm đọc của 汚 là お và 染 là せん (không có biến âm).","translation_vi":"Tình trạng ô nhiễm sông ngòi do nước thải từ nhà máy đang trở thành một vấn đề nghiêm trọng."},{"mondai":1,"q":2,"prompt":"連日の残業で<u>疲労</u>がたまり、体調を崩してしまった。","options":["ひりょう","びろう","ひろう","びりょう"],"answer":3,"word_explain":"疲労（ひろう）: sự mệt mỏi (BÌ LAO). Phân biệt với 肥料（ひりょう: phân bón）và 微量（びりょう: lượng rất nhỏ）.","translation_vi":"Vì làm thêm giờ liên tục nên sự mệt mỏi tích tụ lại và tôi đã bị đổ bệnh."},{"mondai":1,"q":3,"prompt":"休日に美術館へ行き、有名な画家の作品を<u>鑑賞</u>した。","options":["けんしょう","かんしょう","かんそう","けんそう"],"answer":2,"word_explain":"鑑賞（かんしょう）: thưởng thức, thưởng lãm nghệ thuật (GIÁM THƯỞNG). Phân biệt với 感想（かんそう: cảm tưởng）.","translation_vi":"Vào ngày nghỉ, tôi đã đến bảo tàng mỹ thuật và thưởng thức tác phẩm của họa sĩ nổi tiếng."},{"mondai":1,"q":4,"prompt":"相手への<u>配慮</u>が足りず、不快な思いをさせてしまった。","options":["ばいりょ","はいりょう","ばいりょう","はいりょ"],"answer":4,"word_explain":"配慮（はいりょ）: sự quan tâm, cân nhắc, chu đáo (PHỐI LỰ). Chú ý 慮 đọc là りょ (không có trường âm).","translation_vi":"Vì thiếu sự quan tâm cân nhắc đến đối phương nên tôi đã khiến họ cảm thấy khó chịu."},{"mondai":1,"q":5,"prompt":"地球温暖化を防ぐため、二酸化炭素の排出量を<u>削減</u>する必要がある。","options":["しょくげん","しょうげん","さくげん","さっけん"],"answer":3,"word_explain":"削減（さくげん）: cắt giảm (TƯỚC GIẢM). 削 đọc là さく, 減 đọc là げん.","translation_vi":"Để ngăn chặn sự nóng lên toàn cầu, cần thiết phải cắt giảm lượng khí thải carbon dioxide."},{"mondai":2,"q":6,"prompt":"毎日<u>えいよう</u>のバランスを考えた食事を心がけている。","options":["栄誉","栄養","営養","衛養"],"answer":2,"word_explain":"栄養（えいよう）: dinh dưỡng (VINH DƯỠNG). Phân biệt với 栄誉（えいよ: vinh dự）.","translation_vi":"Hằng ngày tôi luôn cố gắng ăn uống cân bằng dinh dưỡng."},{"mondai":2,"q":7,"prompt":"絶滅の危機にある野生動物を<u>ほご</u>する活動に参加した。","options":["保獲","補護","保護","捕護"],"answer":3,"word_explain":"保護（ほご）: bảo vệ (BẢO HỘ). Chữ 保 (bảo) kết hợp với 護 (hộ).","translation_vi":"Tôi đã tham gia hoạt động bảo vệ các loài động vật hoang dã đang đứng trước nguy cơ tuyệt chủng."},{"mondai":2,"q":8,"prompt":"長い練習の成果を、ついに大きな<u>ぶたい</u>で発表する日が来た。","options":["舞体","武台","舞代","舞台"],"answer":4,"word_explain":"舞台（ぶたい）: sân khấu (VŨ ĐÀI). 舞 (múa) + 台 (đài, bệ).","translation_vi":"Ngày công bố thành quả sau thời gian dài luyện tập trên một sân khấu lớn cuối cùng cũng đã đến."},{"mondai":2,"q":9,"prompt":"反対していた両親を何度も話し合って<u>せっとく</u>した。","options":["説得","設得","説徳","設徳"],"answer":1,"word_explain":"説得（せっとく）: thuyết phục (THUYẾT ĐẮC). Chú ý 説 (nói, giải thích) và 得 (đạt được).","translation_vi":"Tôi đã nói chuyện nhiều lần và thuyết phục được bố mẹ vốn đang phản đối."},{"mondai":2,"q":10,"prompt":"しっかり休養をとったおかげで、体力がすっかり<u>かいふく</u>した。","options":["改復","回復","回複","開復"],"answer":2,"word_explain":"回復（かいふく）: hồi phục, khôi phục (HỒI PHỤC). Dùng cho thể lực, sức khỏe, kinh tế, thời tiết...","translation_vi":"Nhờ nghỉ ngơi đầy đủ mà thể lực của tôi đã hồi phục hoàn toàn."},{"mondai":3,"q":11,"prompt":"使わなくなったガラス瓶を洗って(　　)利用する取り組みが広がっている。","options":["再","副","反","複"],"answer":1,"word_explain":"再利用（さいりよう）: tái sử dụng. Tiền tố 再（さい-）mang nghĩa \"lại, lần nữa, tái\".","translation_vi":"Hoạt động rửa sạch và tái sử dụng những chai thủy tinh không dùng nữa đang ngày càng lan rộng."},{"mondai":3,"q":12,"prompt":"最近は、健康のために(　　)添加の食品を選ぶ消費者が増えている。","options":["非","未","不","無"],"answer":4,"word_explain":"無添加（むてんか）: không chất phụ gia. Tiền tố 無（む-）mang nghĩa \"không có\" (無農薬, 無添加, 無香料).","translation_vi":"Gần đây, số người tiêu dùng chọn thực phẩm không chất phụ gia vì sức khỏe đang tăng lên."},{"mondai":3,"q":13,"prompt":"この通りには、昔ながらの和(　　)の建物が立ち並んでいる。","options":["産","風","製","制"],"answer":2,"word_explain":"和風（わふう）: phong cách Nhật Bản. Hậu tố 〜風（ふう）mang nghĩa \"kiểu, phong cách\" (和風, 洋風, 中華風).","translation_vi":"Trên con phố này có rất nhiều tòa nhà mang phong cách Nhật Bản cổ xưa nằm san sát nhau."},{"mondai":4,"q":14,"prompt":"使っていない部屋の電気をこまめに消すなど、日頃から電気の(　　)を心がけている。","options":["節約","省略","短縮","縮小"],"answer":1,"word_explain":"節約（せつやく）: tiết kiệm (điện, nước, chi phí). 省略: lược bỏ; 短縮: rút ngắn thời gian; 縮小: thu nhỏ quy mô.","translation_vi":"Tôi luôn chú ý tiết kiệm điện hằng ngày, chẳng hạn như tắt đèn thường xuyên ở những phòng không sử dụng."},{"mondai":4,"q":15,"prompt":"健康を維持するためには、バランスの良い食事と(　　)運動が欠かせない。","options":["過大な","適度な","極端な","曖昧な"],"answer":2,"word_explain":"適度な（てきどな）: vừa phải, điều độ. 過大な: quá mức; 極端な: cực đoan; 曖昧な: mơ hồ.","translation_vi":"Để duy trì sức khỏe, chế độ ăn uống cân bằng và việc vận động điều độ là không thể thiếu."},{"mondai":4,"q":16,"prompt":"スマートフォンの急速な(　　)により、人々のコミュニケーションの形が大きく変わった。","options":["維持","蓄積","普及","継続"],"answer":3,"word_explain":"普及（ふきゅう）: sự phổ cập, lan rộng. 維持: duy trì; 蓄積: tích lũy; 継続: tiếp tục.","translation_vi":"Nhờ sự phổ cập nhanh chóng của điện thoại thông minh, hình thức giao tiếp của con người đã thay đổi lớn."},{"mondai":4,"q":17,"prompt":"先生の説明を聞きながら、学生たちは納得したように何度も(　　)いた。","options":["つぶやいて","うなずいて","ささやいて","ためらって"],"answer":2,"word_explain":"うなずく: gật đầu (biểu thị sự đồng ý, hiểu bài). つぶやく: lẩm bẩm; ささやく: thì thầm; ためらう: do dự.","translation_vi":"Vừa nghe giải thích của thầy giáo, các sinh viên vừa gật đầu nhiều lần như thể đã hiểu rõ."},{"mondai":4,"q":18,"prompt":"昨日はハイキングでたくさん歩いたので、夜は朝まで(　　)眠れた。","options":["うっかり","はっきり","じっくり","ぐっすり"],"answer":4,"word_explain":"ぐっすり: ngủ say giấc (thường đi với 眠る / 寝る). うっかり: lỡ quên/sơ ý; はっきり: rõ ràng; じっくり: kỹ lưỡng, thong thả.","translation_vi":"Hôm qua tôi đã đi bộ rất nhiều trong chuyến dã ngoại nên tối đã ngủ say một mạch đến sáng."},{"mondai":4,"q":19,"prompt":"この土地はきれいな地下水が(　　)なため、昔からおいしいお酒が作られている。","options":["豊富","豪華","派手","過剰"],"answer":1,"word_explain":"豊富（ほうふ）: phong phú, dồi dào (tài nguyên, nước, dinh dưỡng). 豪華: xa hoa; 派手: sặc sỡ; 過剰: dư thừa quá mức.","translation_vi":"Vì vùng đất này có nguồn nước ngầm sạch dồi dào nên từ xưa đã làm ra được loại rượu rất ngon."},{"mondai":4,"q":20,"prompt":"最初は緊張して話せなかったが、共通の趣味があることがわかるとすぐに(　　)。","options":["行き詰まった","打ち解けた","割り込んだ","引き受けた"],"answer":2,"word_explain":"打ち解ける（うちとける）: cởi mở, hòa hợp, hết ngại ngùng. 行き詰まる: bế tắc; 割り込む: chen ngang; 引き受ける: đảm nhận.","translation_vi":"Ban đầu tôi căng thẳng không nói chuyện được, nhưng khi biết có chung sở thích thì chúng tôi lập tức trở nên cởi mở, thân thiết."},{"mondai":5,"q":21,"prompt":"朝の散歩をしたら、頭が<u>すっきり</u>した。","options":["重く","痛く","さわやかに","あたたかく"],"answer":3,"word_explain":"すっきりする: sảng khoái, nhẹ nhõm, thông suốt ≈ さわやかになる (sảng khoái, dễ chịu).","translation_vi":"Sau khi đi dạo buổi sáng, đầu óc tôi trở nên sảng khoái, tỉnh táo hẳn."},{"mondai":5,"q":22,"prompt":"改善点があれば、遠慮せずに<u>率直な</u>意見を聞かせてください。","options":["正直な","丁寧な","複雑な","慎重な"],"answer":1,"word_explain":"率直な（そっちょくな）: thẳng thắn, không che giấu ≈ 正直な（しょうじきな: thành thật, thẳng thắn）.","translation_vi":"Nếu có điểm nào cần cải thiện, xin đừng ngại mà hãy cho tôi nghe ý kiến thẳng thắn của bạn."},{"mondai":5,"q":23,"prompt":"ここ数十年で、世界の平均気温は<u>急激に</u>上昇している。","options":["少しずつ","急に大きく","ゆっくりと","ほとんど"],"answer":2,"word_explain":"急激に（きゅうげきに）: đột ngột và mạnh mẽ ≈ 急に大きく (nhanh và mạnh).","translation_vi":"Trong vài thập kỷ gần đây, nhiệt độ trung bình của thế giới đang tăng lên một cách đột ngột và mạnh mẽ."},{"mondai":5,"q":24,"prompt":"この博物館では、伝統的な技術を活かした<u>ユニークな</u>展示が楽しめる。","options":["昔からある普通の","非常に高価な","とても静かな","ほかにはない珍しい"],"answer":4,"word_explain":"ユニークな (unique): độc đáo, khác biệt ≈ ほかにはない珍しい (hiếm có, không nơi nào khác có).","translation_vi":"Tại bảo tàng này, bạn có thể thưởng thức những trưng bày độc đáo tận dụng kỹ thuật truyền thống."},{"mondai":5,"q":25,"prompt":"毎日<u>わずかな</u>時間でもストレッチを続けると、体の調子が良くなる。","options":["かなりの","十分な","ほんの少しの","決まった"],"answer":3,"word_explain":"わずかな: ít ỏi, chút ít ≈ ほんの少しの (chỉ một chút).","translation_vi":"Nếu duy trì giãn cơ mỗi ngày dù chỉ một chút thời gian ngắn, tình trạng cơ thể sẽ tốt hơn."},{"mondai":6,"q":26,"prompt":"改善","options":["新しいパソコンを買って、古いパソコンを<u>改善</u>した。","食生活を<u>改善</u>したおかげで、以前より疲れにくくなった。","道に迷ったので、駅員に正しい道を<u>改善</u>してもらった。","風邪を引いて熱が出たので、病院で薬を<u>改善</u>してもらった。"],"answer":2,"word_explain":"改善（かいぜん）: cải thiện (làm cho tình trạng, thói quen, môi trường tốt hơn). Câu 1 phải dùng 買い替えた, câu 3 dùng 教えてもらった, câu 4 dùng 処方してもらった.","translation_vi":"Nhờ cải thiện chế độ ăn uống mà tôi trở nên ít bị mệt hơn trước đây."},{"mondai":6,"q":27,"prompt":"ささやく","options":["会場の後ろの人にも聞こえるように、マイクで大きく<u>ささやいた</u>。","雨が窓ガラスに激しく<u>ささやく</u>音で目が覚めた。","演奏が始まったので、隣の友人に小さい声で<u>ささやいた</u>。","犬が知らない人を見て、大きな声で<u>ささやいた</u>。"],"answer":3,"word_explain":"ささやく: thì thầm, nói nhỏ sát tai. Câu 1 và 4 sai vì dùng với 大きく/大きな声で; câu 2 sai vì mưa đập mạnh vào kính phải dùng 叩く/当たる.","translation_vi":"Vì buổi biểu diễn đã bắt đầu nên tôi nói thì thầm bằng giọng nhỏ với người bạn ngồi bên cạnh."},{"mondai":6,"q":28,"prompt":"手間","options":["手作りの料理は<u>手間</u>がかかるが、その分おいしい。","今日は仕事が早く終わったので、<u>手間</u>が余っている。","重い荷物を運ぶために、友達の<u>手間</u>を借りた。","この機械はとても便利なので、<u>手間</u>が広くなった。"],"answer":1,"word_explain":"手間（てま）: công sức, thời gian bỏ ra (hay đi với 手間がかかる / 手間を省く). Câu 2 phải dùng 時間, câu 3 dùng 手を借りた, câu 4 không có cách nói 手間が広くなった.","translation_vi":"Món ăn tự làm tuy tốn công sức nhưng bù lại rất ngon."},{"mondai":6,"q":29,"prompt":"ふさわしい","options":["この靴はサイズが小さすぎて、私の足に<u>ふさわしくない</u>。","部屋が暗くて本を読むのに<u>ふさわしい</u>ので、電気をつけた。","今日の気温は20度で、とても<u>ふさわしい</u>天気だ。","卒業式には、フォーマルな服装で出席するのが<u>ふさわしい</u>。"],"answer":4,"word_explain":"ふさわしい: phù hợp, tương xứng (về hoàn cảnh, địa vị, mục đích). Câu 1 kích cỡ phải dùng 合わない; câu 2 ngược nghĩa; câu 3 thời tiết dễ chịu dùng 過ごしやすい.","translation_vi":"Vào lễ tốt nghiệp, việc tham dự với trang phục trang trọng là phù hợp."},{"mondai":6,"q":30,"prompt":"きっかけ","options":["台風が近づいている<u>きっかけ</u>で、明日の試合は中止になった。","日本文化に興味を持った<u>きっかけ</u>は、高校のときに見た映画だった。","駅の改札を出たところで、偶然昔の同級生と<u>きっかけ</u>した。","毎日運動を続けるための<u>きっかけ</u>を、冷蔵庫に貼っておいた。"],"answer":2,"word_explain":"きっかけ: cơ duyên, động lực khởi đầu cho một việc gì đó. Câu 1 nguyên nhân sự cố dùng せいで/ため; câu 3 きっかけ không phải danh động từ する; câu 4 phải dùng 目標/メモ.","translation_vi":"Cơ duyên khiến tôi có hứng thú với văn hóa Nhật Bản là bộ phim đã xem hồi cấp ba."},{"mondai":7,"q":31,"prompt":"都市化が進む(　　)、この地域の緑地は年々減少している。","options":["に伴って","に対して","にとって","について"],"answer":1,"word_explain":"〜に伴って（にともなって）: đi kèm với, cùng với sự biến đổi của A thì B cũng thay đổi theo.","translation_vi":"Cùng với quá trình đô thị hóa tiến triển, diện tích cây xanh của khu vực này đang giảm dần qua từng năm."},{"mondai":7,"q":32,"prompt":"昨夜は10時間近く寝た(　　)、今朝もまだ眠気が取れない。","options":["おかげで","にもかかわらず","ばかりに","どころか"],"answer":2,"word_explain":"〜にもかかわらず: mặc dù (diễn tả kết quả trái ngược với dự đoán).","translation_vi":"Mặc dù tối qua tôi đã ngủ gần 10 tiếng nhưng sáng nay cơn buồn ngủ vẫn chưa hết."},{"mondai":7,"q":33,"prompt":"来月から始まる海外留学のことを考えると、今から楽しみ(　　)。","options":["にかぎらない","にすぎない","でならない","とはかぎらない"],"answer":3,"word_explain":"〜てならない / 〜でならない: vô cùng, không thể kìm nén được cảm xúc tự nhiên dâng trào.","translation_vi":"Nghĩ đến chuyến du học nước ngoài bắt đầu từ tháng sau, ngay từ bây giờ tôi đã thấy vô cùng háo hức."},{"mondai":7,"q":34,"prompt":"新しいゴミ処理場の建設(　　)、住民と市役所の間で激しい議論が続いている。","options":["をはじめ","をきっかけに","をめぐって","をもとに"],"answer":3,"word_explain":"〜をめぐって: xoay quanh một vấn đề (thường đi với các từ tranh luận, đối lập như 議論, 対立, 争い).","translation_vi":"Xoay quanh việc xây dựng nhà máy xử lý rác mới, cuộc tranh luận gay gắt giữa người dân và tòa thị chính vẫn đang tiếp diễn."},{"mondai":7,"q":35,"prompt":"健康に良いからといって、毎日同じ野菜ばかり食べればいい(　　)。","options":["にちがいない","わけにはいかない","ことになっている","わけではない"],"answer":4,"word_explain":"〜からといって〜わけではない: dù nói là A nhưng không hẳn là B (phủ định một phần).","translation_vi":"Dù nói là tốt cho sức khỏe nhưng không hẳn là ngày nào cũng chỉ cần ăn mãi một loại rau là được."},{"mondai":7,"q":36,"prompt":"このスープは温かい(　　)召し上がってください。冷めると味が落ちてしまいます。","options":["うちに","ままに","わりに","くせに"],"answer":1,"word_explain":"〜うちに: trong lúc trạng thái vẫn còn duy trì (trước khi thay đổi sang trạng thái khác).","translation_vi":"Món súp này xin hãy dùng lúc còn nóng. Nếu nguội đi thì hương vị sẽ giảm mất."},{"mondai":7,"q":37,"prompt":"この伝統的な祭りは、地元の人々(　　)、海外からの観光客にも大変人気がある。","options":["どころか","ばかりか","だけあって","にしては"],"answer":2,"word_explain":"〜ばかりか〜も: không chỉ A mà thậm chí cả B.","translation_vi":"Lễ hội truyền thống này không chỉ được người dân địa phương mà còn được cả du khách nước ngoài vô cùng yêu thích."},{"mondai":7,"q":38,"prompt":"体調が少し悪いが、大切なプレゼンの日なので、会社を休む(　　)。","options":["はずがない","わけがない","わけにはいかない","にちがいない"],"answer":3,"word_explain":"〜わけにはいかない: không thể làm việc đó được (do lý do trách nhiệm, hoàn cảnh, tâm lý hoặc đạo đức).","translation_vi":"Tuy trong người hơi không khỏe nhưng vì là ngày thuyết trình quan trọng nên tôi không thể nghỉ làm được."},{"mondai":7,"q":39,"prompt":"この映画は、実際にあった出来事(　　)作られた作品だ。","options":["を中心に","をもとに","を込めて","を問わず"],"answer":2,"word_explain":"〜をもとに: dựa trên, lấy làm cơ sở/nguyên liệu để tạo ra tác phẩm, kế hoạch, ý kiến.","translation_vi":"Bộ phim này là tác phẩm được dựng lên dựa trên một sự việc có thật."},{"mondai":7,"q":40,"prompt":"大雨による土砂崩れの恐れがあるため、今日の野外イベントは中止(　　)。","options":["しかねる","せざるを得ない","するわけがない","しないわけではない"],"answer":2,"word_explain":"〜ざるを得ない: đành phải, buộc phải làm (dù không muốn). Chú ý động từ する chia thành せざるを得ない.","translation_vi":"Vì có nguy cơ sạt lở đất do mưa lớn nên sự kiện ngoài trời hôm nay đành phải hủy bỏ."},{"mondai":7,"q":41,"prompt":"検査の結果がわかり(　　)、すぐにご連絡いたします。","options":["ながら","つつ","しだい","きり"],"answer":3,"word_explain":"Vます + しだい: ngay sau khi làm xong A thì sẽ lập tức làm B (thường dùng trong văn phong trang trọng, thông báo).","translation_vi":"Ngay sau khi biết kết quả kiểm tra, chúng tôi sẽ liên lạc ngay với quý khách."},{"mondai":7,"q":42,"prompt":"睡眠不足の状態が長く続くと、大きな病気につながり(　　)。","options":["かねない","かねる","がたい","きれない"],"answer":1,"word_explain":"Vます + かねない: có nguy cơ, rất có thể dẫn đến một kết quả xấu. Phân biệt với かねる (khó lòng làm được).","translation_vi":"Nếu tình trạng thiếu ngủ kéo dài thì rất có nguy cơ dẫn đến bệnh nặng."},{"mondai":8,"q":43,"prompt":"地球環境を守るためには、＿＿＿　＿＿＿　★　＿＿＿　ことが大切だ。","options":["見直す","生活を","一人ひとりが","普段の"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → 2 → 1 (一人ひとりが → 普段の → 生活を → 見直す). Vị trí ★ là đáp án 2 (生活を).","translation_vi":"Để bảo vệ môi trường Trái Đất, điều quan trọng là mỗi người chúng ta cần xem xét lại cuộc sống thường ngày của mình."},{"mondai":8,"q":44,"prompt":"バランスの良い　＿＿＿　＿＿＿　★　＿＿＿、風邪を引きにくくなった。","options":["してから","食事を","ように","心がける"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → 3 → 1 (食事を → 心がける → ように → してから). Cấu trúc Vる + ようにしてから (từ khi bắt đầu cố gắng/tạo thói quen). Vị trí ★ là đáp án 3 (ように).","translation_vi":"Kể từ khi bắt đầu cố gắng duy trì chế độ ăn uống cân bằng, tôi trở nên ít bị cảm cúm hơn."},{"mondai":8,"q":45,"prompt":"茶道や華道　＿＿＿　＿＿＿　★　＿＿＿、強い関心を持つ外国人が増えている。","options":["日本の","とする","伝統文化に","をはじめ"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → 1 → 3 (をはじめ → とする → 日本の → 伝統文化に). Cấu trúc N1をはじめとするN2 (N2 tiêu biểu như N1). Vị trí ★ là đáp án 1 (日本の).","translation_vi":"Ngày càng có nhiều người nước ngoài dành sự quan tâm mạnh mẽ cho văn hóa truyền thống Nhật Bản, tiêu biểu như trà đạo và cắm hoa."},{"mondai":8,"q":46,"prompt":"相手の話を最後まで　＿＿＿　＿＿＿　★　＿＿＿　よくないと思う。","options":["主張するのは","自分の","聞かずに","意見ばかり"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 2 → 4 → 1 (聞かずに → 自分の → 意見ばかり → 主張するのは). Cấu trúc Vずに (mà không làm) và Nばかり (chỉ toàn). Vị trí ★ là đáp án 4 (意見ばかり).","translation_vi":"Tôi nghĩ việc không nghe hết lời đối phương mà chỉ toàn khăng khăng bảo vệ ý kiến của bản thân là không tốt."},{"mondai":8,"q":47,"prompt":"病気に　＿＿＿　＿＿＿　★　＿＿＿　ありがたさに気づいた。","options":["いられることの","毎日健康で","初めて、","なって"],"answer":2,"word_explain":"Thứ tự đúng: 4 → 3 → 2 → 1 (なって → 初めて、 → 毎日健康で → いられることの). Cấu trúc Vて初めて (chỉ sau khi... mới nhận ra). Vị trí ★ là đáp án 2 (毎日健康で).","translation_vi":"Chỉ sau khi bị bệnh, tôi mới nhận ra sự đáng quý của việc mỗi ngày có thể sống khỏe mạnh."}]},{"id":"moshi_04","displayName":"Đề thi thử số 4 (Nước rút — Độ khó cao)","subtitle":"47 câu • Full Mondai 1–8 (Từ vựng + Ngữ pháp)","badge":"Đề thi thử #4","questions":[{"mondai":1,"q":1,"prompt":"売上高の減少を<u>補う</u>ため、同社は海外市場の開拓に力を入れている。","options":["おぎなう","ととのう","うやまう","やしなう"],"answer":1,"word_explain":"補う（おぎなう）: bù đắp, bổ sung (phần thiếu hụt). Các phương án nhiễu: 整う（ととのう - chỉnh tề/sẵn sàng）, 敬う（うやまう - kính trọng）, 養う（やしなう - nuôi dưỡng）.","translation_vi":"Để bù đắp cho sự sụt giảm doanh thu, công ty đó đang dồn lực vào việc khai thác thị trường nước ngoài."},{"mondai":1,"q":2,"prompt":"会議では、環境への配慮を<u>怠った</u>企業の責任が厳しく追及された。","options":["いたった","おこたった","あせった","たもった"],"answer":2,"word_explain":"怠る（おこたる）: lơ là, xao nhãng, chểnh mảng (bổn phận, sự chú ý). Các phương án nhiễu: 至る（いたる）, 焦る（あせる）, 保つ（たもつ）.","translation_vi":"Tại cuộc họp, trách nhiệm của doanh nghiệp lơ là việc quan tâm đến môi trường đã bị truy cứu gay gắt."},{"mondai":1,"q":3,"prompt":"長年、再生可能エネルギーの研究に<u>携わって</u>きた技術者が表彰された。","options":["かかわって","そなわって","たずさわって","くわわって"],"answer":3,"word_explain":"携わる（たずさわる）: tham gia vào, gắn bó với, phụ trách (công việc, dự án quan trọng). Lưu ý phân biệt với 関わる（かかわる - liên quan đến）.","translation_vi":"Kỹ sư đã gắn bó nhiều năm với công tác nghiên cứu năng lượng tái tạo vừa được tuyên dương."},{"mondai":1,"q":4,"prompt":"今年の冬は記録的な大雪に見舞われ、交通機関が大幅に<u>滞った</u>。","options":["おちいった","したがった","さからった","とどこおった"],"answer":4,"word_explain":"滞る（とどこおる）: đình trệ, ứ đọng, chậm trễ (giao thông, công việc, thanh toán). Các phương án nhiễu: 陥る（おちいる）, 従う（したがう）, 逆らう（さからう）.","translation_vi":"Mùa đông năm nay hứng chịu trận tuyết lớn kỷ lục, khiến các phương tiện giao thông bị đình trệ nghiêm trọng."},{"mondai":1,"q":5,"prompt":"契約書の内容に<u>相違</u>がないか、署名する前に隅々まで確認してください。","options":["そうい","しょうい","そうち","しょうち"],"answer":1,"word_explain":"相違（そうい）: sự khác biệt, sai khác (dùng trong văn viết, hợp đồng: 相違ない - không có gì sai khác). Lưu ý âm đọc là そうい, không phải しょうい.","translation_vi":"Trước khi ký tên, xin vui lòng kiểm tra kỹ từng chi tiết xem nội dung hợp đồng có điểm nào sai khác không."},{"mondai":2,"q":6,"prompt":"住民からの強い要請を受けて、市役所は条例の<u>かいせい</u>に踏み切った。","options":["改政","改正","改制","改整"],"answer":2,"word_explain":"改正（かいせい）: sửa đổi, tu chính (luật pháp, quy định, chế độ, bảng giờ tàu cho đúng/tốt hơn). Tránh nhầm với các từ ghép sai chữ Hán như 改政, 改制, 改整.","translation_vi":"Trước yêu cầu mạnh mẽ từ người dân, tòa thị chính đã quyết định tiến hành sửa đổi sắc lệnh địa phương."},{"mondai":2,"q":7,"prompt":"限られた予算の中で最大の成果を上げるため、経費を<u>さくげん</u>する必要がある。","options":["削除","削滅","削減","削限"],"answer":3,"word_explain":"削減（さくげん）: cắt giảm (chi phí, ngân sách, nhân sự, khí thải). Lưu ý phân biệt với 削除（さくじょ - xóa bỏ dữ liệu/văn bản）.","translation_vi":"Để đạt được hiệu quả tối đa trong ngân sách hạn hẹp, cần phải cắt giảm chi phí."},{"mondai":2,"q":8,"prompt":"彼はどんなに困難な状況に置かれても、決して<u>だきょう</u>しようとしなかった。","options":["妥協","堕協","妥競","堕競"],"answer":1,"word_explain":"妥協（だきょう）: thỏa hiệp, nhượng bộ. Chữ 妥 (thỏa đáng) ghép với 協 (hiệp lực), không dùng 堕 (đọa) hay 競 (cạnh tranh).","translation_vi":"Dù bị đặt vào hoàn cảnh khó khăn đến đâu, anh ấy cũng tuyệt đối không chịu thỏa hiệp."},{"mondai":2,"q":9,"prompt":"衛生管理を<u>てってい</u>することで、食中毒の発生を未然に防ぐことができる。","options":["徹定","撤定","撤底","徹底"],"answer":4,"word_explain":"徹底（てってい）: triệt để, làm đến nơi đến chốn. Chú ý bộ 彳 trong 徹 (triệt) và chữ 底 (để - đáy), dễ nhầm với 撤 (triệt thoái) và 定 (định).","translation_vi":"Bằng việc thực hiện triệt để công tác quản lý vệ sinh, chúng ta có thể phòng ngừa ngộ độc thực phẩm từ trước khi xảy ra."},{"mondai":2,"q":10,"prompt":"異文化との触れ合いは、若い世代の創造性を大いに<u>しげき</u>する。","options":["刺劇","刺激","指劇","指摘"],"answer":2,"word_explain":"刺激（しげき）: kích thích. Lưu ý chữ 激 (kích động) có bộ thủy 氵, không phải 劇 (kịch), và không nhầm với 指摘（してき - chỉ ra）.","translation_vi":"Việc tiếp xúc với các nền văn hóa khác sẽ kích thích mạnh mẽ khả năng sáng tạo của thế hệ trẻ."},{"mondai":3,"q":11,"prompt":"今年は4月だというのに、真夏（　　）の厳しい暑さが続いている。","options":["並み","通り","向け","風"],"answer":1,"word_explain":"～並み（なみ）: ngang tầm, tương đương với mức độ của N (真夏並みの暑さ = cái nóng ngang với giữa hè). 通り (theo đúng), 向け (dành cho), 風 (kiểu/phong cách) đều không hợp nghĩa.","translation_vi":"Năm nay mới tháng 4 nhưng cái nóng gay gắt ngang ngửa giữa mùa hè vẫn đang kéo dài."},{"mondai":3,"q":12,"prompt":"窓（　　）に外を眺めていると、いつの間にか雨が雪に変わっていた。","options":["向き","越し","沿い","掛け"],"answer":2,"word_explain":"～越し（ごし）: xuyên qua, qua lớp ngăn cách (窓越しに = qua cửa sổ, 電話越しに = qua điện thoại). 沿い (dọc theo), 向き (hướng về), 掛け (đang dở/treo) không phù hợp.","translation_vi":"Khi đang ngắm ra ngoài qua ô cửa sổ, lúc nào không hay mưa đã chuyển thành tuyết."},{"mondai":3,"q":13,"prompt":"この職場は（　　）経験の人でも安心して働けるように、研修制度が充実している。","options":["不","非","未","反"],"answer":3,"word_explain":"未～（み～）: chưa (未経験 = chưa có kinh nghiệm, 未完成 = chưa hoàn thành). Các tiền tố 不, 非, 反 không kết hợp với 経験.","translation_vi":"Nơi làm việc này có chế độ đào tạo rất đầy đủ để ngay cả những người chưa có kinh nghiệm cũng có thể yên tâm làm việc."},{"mondai":4,"q":14,"prompt":"新製品の試作品について顧客アンケートを実施したところ、（　　）好評を得ることができた。","options":["おおむね","ひたすら","すかさず","しきりに"],"answer":1,"word_explain":"おおむね: nhìn chung, đại khái, phần lớn (thường dùng trong báo cáo, văn trang trọng). ひたすら (miệt mài), すかさず (ngay lập tức không chần chừ), しきりに (liên tục, không ngừng).","translation_vi":"Khi tiến hành khảo sát khách hàng về sản phẩm thử nghiệm mới, nhìn chung chúng tôi đã nhận được đánh giá tốt."},{"mondai":4,"q":15,"prompt":"度重なる議論の末、委員会は当初の計画を白紙に戻すという結論に（　　）。","options":["及んだ","至った","沿った","富んだ"],"answer":2,"word_explain":"結論に至る（けつろんにいたる）: đi đến kết luận (cụm cố định mang tính trang trọng). 及ぶ (lan tới/sánh bằng), 沿う (dọc theo/phù hợp với), 富む (giàu có về).","translation_vi":"Sau nhiều lần tranh luận, ủy ban đã đi đến kết luận là hủy bỏ kế hoạch ban đầu để làm lại từ đầu."},{"mondai":4,"q":16,"prompt":"プロジェクトを期限内に完了させるためには、各部署間の緊密な（　　）が不可欠だ。","options":["連想","連結","連携","連続"],"answer":3,"word_explain":"連携（れんけい）: sự liên kết, phối hợp nhịp nhàng cùng thực hiện một mục tiêu (緊密な連携). 連想 (liên tưởng), 連結 (nối liền vật lý như toa tàu), 連続 (liên tiếp).","translation_vi":"Để hoàn thành dự án đúng thời hạn, sự phối hợp chặt chẽ giữa các phòng ban là điều không thể thiếu."},{"mondai":4,"q":17,"prompt":"この地域の伝統工芸は、後継者不足により存続が（　　）状況にある。","options":["険しい","激しい","乏しい","危うい"],"answer":4,"word_explain":"危うい（あやうい）: bấp bênh, nguy hiểm, có nguy cơ mất đi (存続が危うい = sự tồn tại bị đe dọa). 険しい (hiểm trở/nghiêm khắc), 激しい (dữ dội), 乏しい (nghèo nàn, thiếu thốn).","translation_vi":"Nghề thủ công truyền thống của khu vực này đang ở trong tình trạng bấp bênh về sự tồn tại do thiếu người kế thừa."},{"mondai":4,"q":18,"prompt":"新規事業を立ち上げるにあたり、経験豊富な専門家を招いて運営の（　　）を学ぶことにした。","options":["ノウハウ","キャッチフレーズ","ジレンマ","ニュアンス"],"answer":1,"word_explain":"ノウハウ (know-how): bí quyết, kiến thức và kỹ năng thực tiễn. キャッチフレーズ (khẩu hiệu quảng cáo), ジレンマ (tình thế tiến thoái lưỡng nan), ニュアンス (sắc thái).","translation_vi":"Khi khởi động mảng kinh doanh mới, chúng tôi đã quyết định mời chuyên gia giàu kinh nghiệm để học hỏi bí quyết vận hành."},{"mondai":4,"q":19,"prompt":"周囲の反対を（　　）、彼女は単身で海外留学へと旅立った。","options":["引き取って","押し切って","受け持って","取り戻して"],"answer":2,"word_explain":"押し切る（おしきる）: vượt qua, làm tới cùng bất chấp (反対を押し切る = bất chấp sự phản đối). 引き取る (tiếp nhận/nhận về), 受け持つ (đảm nhận), 取り戻す (lấy lại).","translation_vi":"Bất chấp sự phản đối của mọi người xung quanh, cô ấy đã một mình lên đường đi du học nước ngoài."},{"mondai":4,"q":20,"prompt":"重要なプレゼンテーションを明日に控え、彼は緊張のあまり（　　）と落ち着かない様子だった。","options":["しみじみ","すらすら","そわそわ","こつこつ"],"answer":3,"word_explain":"そわそわ: bồn chồn, lo lắng không yên (đi với 落ち着かない). しみじみ (thấm thía), すらすら (trôi chảy), こつこつ (cần cù từng chút một).","translation_vi":"Trước buổi thuyết trình quan trọng vào ngày mai, anh ấy căng thẳng đến mức bồn chồn đứng ngồi không yên."},{"mondai":5,"q":21,"prompt":"彼の説明は<u>簡潔</u>で、専門外の人にも非常に分かりやすかった。","options":["長くて詳しい","短くてまとまっている","複雑で難しい","丁寧で優しい"],"answer":2,"word_explain":"簡潔（かんけつ）: ngắn gọn, súc tích, rõ ràng = 短くてまとまっている.","translation_vi":"Lời giải thích của anh ấy rất ngắn gọn súc tích, nên ngay cả người ngoài chuyên ngành cũng rất dễ hiểu."},{"mondai":5,"q":22,"prompt":"台風の接近に伴い、明日予定されていた屋外イベントは<u>やむを得ず</u>中止となった。","options":["予想通りに","予定より早く","しかたなく","突然に"],"answer":3,"word_explain":"やむを得ず（やむをえず）: bất đắc dĩ, đành phải, không còn cách nào khác = しかたなく.","translation_vi":"Do bão đang tiến gần, sự kiện ngoài trời dự kiến diễn ra vào ngày mai đành phải hủy bỏ vì bất khả kháng."},{"mondai":5,"q":23,"prompt":"今回の調査では、消費者の購買行動に<u>顕著な</u>変化が見られた。","options":["わずかな","一時的な","意外な","はっきりした"],"answer":4,"word_explain":"顕著な（けんちょな）: rõ rệt, nổi bật, dễ nhận thấy = はっきりした. Các phương án nhiễu: わずかな (chút ít), 一時的な (tạm thời), 意外な (bất ngờ).","translation_vi":"Trong cuộc khảo sát lần này, có thể thấy sự thay đổi rõ rệt trong hành vi mua sắm của người tiêu dùng."},{"mondai":5,"q":24,"prompt":"どんなに忙しくても、基本的な確認作業を<u>おろそかにする</u>べきではない。","options":["いいかげんにする","後回しにする","他人に任せる","最初から諦める"],"answer":1,"word_explain":"おろそかにする: xem nhẹ, lơ là, làm qua loa đại khái = いいかげんにする. Tránh nhầm với 後回しにする (để lại sau).","translation_vi":"Dù bận rộn đến mấy cũng không nên xem nhẹ công việc kiểm tra cơ bản."},{"mondai":5,"q":25,"prompt":"両社の交渉は平行線をたどり、ついに<u>決裂</u>した。","options":["まとまった","延期された","壊れて終わった","再開された"],"answer":3,"word_explain":"決裂する（けつれつする）: đổ vỡ, tan vỡ (đàm phán, quan hệ) = 壊れて終わった. (平行線をたどる = đi song song không tìm được tiếng nói chung).","translation_vi":"Cuộc đàm phán giữa hai công ty đi vào bế tắc và cuối cùng đã đổ vỡ."},{"mondai":6,"q":26,"prompt":"めど","options":["新しい工場の建設は順調に進んでおり、来月半ばには完成の<u>めど</u>が立った。","このレストランは駅からの<u>めど</u>が良いので、週末はいつも混雑している。","彼は将来の<u>めど</u>に向かって、毎日欠かさず英語の勉強を続けている。","地図を見ながら歩いたが、<u>めど</u>となる大きな建物が見つからず迷ってしまった。"],"answer":1,"word_explain":"めど: triển vọng, mốc dự kiến hoàn thành/giải quyết (cụm cố định: めどが立つ / めどがつく). Câu 2 sai (phải dùng アクセス/立地), câu 3 sai (phải dùng 目標/夢), câu 4 sai (phải dùng 目印).","translation_vi":"Việc xây dựng nhà máy mới đang tiến triển thuận lợi và đã có triển vọng hoàn thành vào giữa tháng sau."},{"mondai":6,"q":27,"prompt":"あえて","options":["明日は大事な試験があるので、今日は<u>あえて</u>早く寝ることにした。","周囲からは反対されたが、私は自分の可能性を試すために<u>あえて</u>厳しい道を選んだ。","電車が遅延したため、<u>あえて</u>会議に遅刻してしまった。","この料理はとても辛いので、辛いものが苦手な人は<u>あえて</u>食べない方がいい。"],"answer":2,"word_explain":"あえて: cố tình, dám (chủ động làm điều khó khăn hoặc trái với lẽ thông thường). Câu 1 là hành động hiển nhiên không cần あえて; câu 3 là kết quả ngoài ý muốn; câu 4 là lời khuyên thông thường.","translation_vi":"Dù bị mọi người xung quanh phản đối, tôi vẫn cố tình chọn con đường chông gai để thử thách khả năng của bản thân."},{"mondai":6,"q":28,"prompt":"見直す","options":["昨日なくした財布を、部屋の隅々まで<u>見直した</u>が見つからなかった。","遠くの景色をきれいに見るために、新しい眼鏡を<u>見直した</u>。","業績の悪化を受けて、会社は現在の販売戦略を根本から<u>見直す</u>ことにした。","駅で偶然昔の上司を<u>見直して</u>、懐かしくなった。"],"answer":3,"word_explain":"見直す（みなおす）: xem xét lại, đánh giá lại (kế hoạch, chế độ, hoặc nhìn nhận lại ai đó theo chiều hướng tích cực hơn). Câu 1 phải dùng 探した, câu 2 sai nghĩa, câu 4 phải dùng 見かけて.","translation_vi":"Trước tình hình kinh doanh sa sút, công ty đã quyết định xem xét lại từ gốc chiến lược bán hàng hiện tại."},{"mondai":6,"q":29,"prompt":"妥当","options":["彼女は誰に対しても礼儀正しく、とても<u>妥当</u>な性格をしている。","今日は風もなく穏やかで、ハイキングには<u>妥当</u>な天気だ。","この部屋は日当たりが良く、一人暮らしには<u>妥当</u>な広さがある。","品質と機能の高さを考えれば、この価格設定は十分に<u>妥当</u>だと言える。"],"answer":4,"word_explain":"妥当（だとう）: thỏa đáng, hợp lý (dùng cho phán đoán, mức giá, biện pháp, kết luận). Không dùng để miêu tả tính cách (câu 1), thời tiết (câu 2), hay diện tích phòng (câu 3).","translation_vi":"Nếu xét đến chất lượng và tính năng cao, có thể nói mức giá này hoàn toàn hợp lý."},{"mondai":6,"q":30,"prompt":"ひとまず","options":["事故の詳しい原因はまだ調査中だが、乗客全員の無事が確認されて<u>ひとまず</u>安心した。","彼は毎日<u>ひとまず</u>ジョギングをして、健康を維持している。","駅に着いたとたん、<u>ひとまず</u>大雨が降り出して傘を差す間もなかった。","この薬は食後に<u>ひとまず</u>二錠ずつ飲んでください。"],"answer":1,"word_explain":"ひとまず: tạm thời, trước mắt (chưa hoàn toàn xong hẳn nhưng tạm ổn định/dừng lại ở một mốc). Không dùng cho thói quen hằng ngày (câu 2), sự việc đột ngột (câu 3 - いきなり), hay hướng dẫn liều lượng (câu 4).","translation_vi":"Nguyên nhân chi tiết của vụ tai nạn vẫn đang được điều tra, nhưng việc xác nhận toàn bộ hành khách đều an toàn giúp tôi tạm thời yên tâm."},{"mondai":7,"q":31,"prompt":"新しい空港の建設（　　）、推進派と反対派の間で激しい議論が続いている。","options":["にわたって","をめぐって","に沿って","に応じて"],"answer":2,"word_explain":"Nをめぐって: xoay quanh vấn đề N (thường đi với tranh luận, xung đột, đối lập giữa các bên). にわたって (trải dài suốt), に沿って (theo đúng), に応じて (tùy theo).","translation_vi":"Xoay quanh việc xây dựng sân bay mới, cuộc tranh luận gay gắt giữa phe ủng hộ và phe phản đối vẫn đang tiếp diễn."},{"mondai":7,"q":32,"prompt":"彼は日本語が堪能な（　　）、英語やフランス語も不自由なく使いこなす。","options":["ばかりか","どころか","ものなら","からには"],"answer":1,"word_explain":"AばかりかBも: không những A mà còn B (bổ sung thông tin cùng chiều). どころか dùng để phủ định/tương phản mức độ (đừng nói là A, thậm chí ngược lại là B).","translation_vi":"Anh ấy không những thông thạo tiếng Nhật mà còn sử dụng thành thạo cả tiếng Anh và tiếng Pháp mà không gặp trở ngại gì."},{"mondai":7,"q":33,"prompt":"原材料費の高騰がこれ以上続けば、商品の値上げを検討（　　）。","options":["するわけにはいかない","せずにはおかない","せざるを得ない","するまい"],"answer":3,"word_explain":"Vない＋ざるを得ない (する → せざるを得ない): đành phải, buộc phải làm (dù không muốn nhưng hoàn cảnh bắt buộc). するわけにはいかない (không thể làm vì lý do đạo đức/xã hội), せずにはおかない (nhất định sẽ khiến...), するまい (quyết không làm).","translation_vi":"Nếu giá nguyên vật liệu tiếp tục tăng cao hơn nữa, chúng tôi buộc lòng phải cân nhắc việc tăng giá sản phẩm."},{"mondai":7,"q":34,"prompt":"今回の試合に向けて誰よりも厳しい練習を積んできた（　　）、敗退したときの悔しさは計り知れない。","options":["くせに","わりに","だけに","ばかりに"],"answer":3,"word_explain":"～だけに: chính vì A nên B lại càng tương xứng (cả tích cực lẫn tiêu cực). ばかりに dùng cho nguyên nhân mang tính sai lầm/đáng tiếc dẫn đến hậu quả xấu; くせに (mặc dù - chê trách); わりに (so với...).","translation_vi":"Chính vì đã tích lũy quá trình tập luyện khắc nghiệt hơn ai hết cho trận đấu lần này, nên nỗi tiếc nuối khi bị loại là không thể đong đếm được."},{"mondai":7,"q":35,"prompt":"新規口座の開設（　　）、本人確認書類のご提示をお願いしております。","options":["に対して","に反して","につれて","に際して"],"answer":4,"word_explain":"Nに際して（にさいして）: nhân dịp, khi thực hiện một việc quan trọng/mang tính trang trọng. に対して (đối với), に反して (trái với), につれて (càng... càng...).","translation_vi":"Nhân dịp / Khi mở tài khoản mới, chúng tôi xin quý khách vui lòng xuất trình giấy tờ xác minh nhân thân."},{"mondai":7,"q":36,"prompt":"このような初歩的なミスを繰り返していては、取引先からの信頼を（　　）。","options":["失いかねない","失いようがない","失いがたい","失いかねる"],"answer":1,"word_explain":"Vます＋かねない: có nguy cơ, có khả năng xảy ra chuyện không hay. Cẩn thận bẫy với Vます＋かねる (khó mà làm được / không thể làm). 失いようがない (không có cách nào để mất), 失いがたい (khó mà mất).","translation_vi":"Nếu cứ lặp đi lặp lại những lỗi sơ đẳng như thế này thì rất có khả năng sẽ đánh mất lòng tin từ đối tác."},{"mondai":7,"q":37,"prompt":"大学を卒業した（　　）、自分が本当にやりたい仕事がまだ見つからずにいる。","options":["ものなら","ものの","ものだから","ものとして"],"answer":2,"word_explain":"～ものの: mặc dù A nhưng thực tế lại B (văn viết/trang trọng). ものなら (nếu có thể...), ものだから (vì... - biện minh), ものとして (với tư cách là...).","translation_vi":"Mặc dù đã tốt nghiệp đại học, tôi vẫn chưa tìm được công việc mà mình thực sự muốn làm."},{"mondai":7,"q":38,"prompt":"このボランティア活動には、年齢や国籍（　　）、誰でも自由に参加することができる。","options":["を込めて","をきっかけに","を問わず","をもとに"],"answer":3,"word_explain":"Nを問わず（をとわず）: không phân biệt, bất kể N. を込めて (gửi gắm tình cảm), をきっかけに (nhân cơ hội/bước ngoặt), をもとに (dựa trên).","translation_vi":"Bất kể tuổi tác hay quốc tịch, bất kỳ ai cũng có thể tự do tham gia hoạt động tình nguyện này."},{"mondai":7,"q":39,"prompt":"締め切りが明日の朝に迫っているので、今はゆっくり食事をする（　　）。","options":["ほかはない","どころではない","にすぎない","わけではない"],"answer":2,"word_explain":"Vる＋どころではない: không phải lúc / hoàn cảnh không cho phép để làm V. ほかはない (không còn cách nào khác ngoài...), にすぎない (chẳng qua chỉ là), わけではない (không hẳn là).","translation_vi":"Vì hạn chót đã sát đến sáng mai rồi nên bây giờ không phải lúc để thong thả ăn uống."},{"mondai":7,"q":40,"prompt":"災害はいつ起こるか分からないので、日頃から非常食を備蓄しておく（　　）。","options":["にすぎない","にほかならない","に相違ない","に越したことはない"],"answer":4,"word_explain":"Vる＋に越したことはない（にこしたことはない）: không gì bằng, tốt hơn hết là nên làm V. にすぎない (chỉ là), にほかならない (chính là, không gì khác ngoài), に相違ない (chắc chắn là).","translation_vi":"Vì không biết thiên tai sẽ xảy ra lúc nào nên tốt hơn hết là dự trữ sẵn thực phẩm khẩn cấp từ ngày thường."},{"mondai":7,"q":41,"prompt":"最新の設備を導入した（　　）、すぐに生産性が向上するわけではない。","options":["からといって","からこそ","からには","からして"],"answer":1,"word_explain":"～からといって（～わけではない）: không phải cứ vì A mà B. からこそ (chính vì), からには (một khi đã), からして (ngay từ A đã thấy...).","translation_vi":"Không phải cứ nói rằng đã đưa thiết bị mới nhất vào sử dụng là năng suất sẽ lập tức tăng lên."},{"mondai":7,"q":42,"prompt":"詳しい日程が決まり（　　）、改めてメールにてご連絡いたします。","options":["ながら","つつ","次第","がてら"],"answer":3,"word_explain":"Vます＋次第（しだい）: ngay sau khi V (văn phong lịch sự, dùng trong công việc, vế sau là hành động trong tương lai). ながら / つつ (vừa... vừa / mặc dù), がてら (nhân tiện).","translation_vi":"Ngay sau khi lịch trình chi tiết được quyết định, tôi sẽ liên hệ lại với quý vị qua email."},{"mondai":8,"q":43,"prompt":"この映画は、＿＿＿　＿＿＿　★　＿＿＿　細部まで実によく作り込まれている。","options":["手がけた","世界的に有名な","だけあって、","監督が"],"answer":1,"word_explain":"Thứ tự đúng: 2 (世界的に有名な) → 4 (監督が) → 1 (手がけた) → 3 (だけあって、). Ngữ pháp ～だけあって (quả xứng danh / chính vì... nên...). Vị trí ★ là 1.","translation_vi":"Bộ phim này quả xứng danh do một đạo diễn nổi tiếng thế giới thực hiện, được trau chuốt cực kỳ kỹ lưỡng đến từng chi tiết nhỏ."},{"mondai":8,"q":44,"prompt":"今回の優勝は、＿＿＿　＿＿＿　★　＿＿＿　によるものだ。","options":["努力も","監督の的確な指導","選手一人ひとりの","さることながら、"],"answer":4,"word_explain":"Thứ tự đúng: 3 (選手一人ひとりの) → 1 (努力も) → 4 (さることながら、) → 2 (監督の的確な指導). Ngữ pháp Aもさることながら、B (A tất nhiên rồi, nhưng B còn đáng nói hơn nữa). Vị trí ★ là 4.","translation_vi":"Chức vô địch lần này không chỉ nhờ nỗ lực của từng tuyển thủ mà hơn hết còn đến từ sự chỉ đạo chính xác của huấn luyện viên."},{"mondai":8,"q":45,"prompt":"相手の立場に　＿＿＿　＿＿＿　★　＿＿＿　見えてこない。","options":["なって","ことには、","考えてみない","本当の問題点は"],"answer":2,"word_explain":"Thứ tự đúng: 1 (なって) → 3 (考えてみない) → 2 (ことには、) → 4 (本当の問題点は). Cụm 相手の立場になる (đặt mình vào vị trí đối phương) + ngữ pháp ～ないことには～ない (nếu không... thì không thể...). Vị trí ★ là 2.","translation_vi":"Nếu không thử đặt mình vào vị trí của đối phương để suy nghĩ thì sẽ không thể nhìn ra vấn đề thực sự."},{"mondai":8,"q":46,"prompt":"AI技術が　＿＿＿　＿＿＿　★　＿＿＿　必ず残るはずだ。","options":["できない仕事は","進歩しようとも、","人間にしか","どれほど"],"answer":3,"word_explain":"Thứ tự đúng: 4 (どれほど) → 2 (進歩しようとも、) → 3 (人間にしか) → 1 (できない仕事は). Ngữ pháp どれほど～ようとも (cho dù... đến mức nào) và ～しか～ない (chỉ...). Vị trí ★ là 3.","translation_vi":"Cho dù công nghệ AI có tiến bộ đến mức nào đi nữa, chắc chắn vẫn sẽ còn lại những công việc mà chỉ con người mới làm được."},{"mondai":8,"q":47,"prompt":"伝統的な技法を　＿＿＿　＿＿＿　★　＿＿＿　高く評価されている。","options":["合うように","守りながらも、","工夫されたデザインが","現代の生活に"],"answer":1,"word_explain":"Thứ tự đúng: 2 (守りながらも、) → 4 (現代の生活に) → 1 (合うように) → 3 (工夫されたデザインが). Cụm 伝統的な技法を守りながらも (dù/vừa giữ gìn kỹ thuật truyền thống) + 現代の生活に合うように工夫されたデザイン (thiết kế được cải tiến để phù hợp với đời sống hiện đại). Vị trí ★ là 1.","translation_vi":"Những thiết kế vừa giữ gìn kỹ thuật truyền thống vừa được sáng tạo sao cho phù hợp với đời sống hiện đại đang được đánh giá rất cao."}]}];
